window.DOSIK=window.DOSIK||{};DOSIK["cp_acct"]={"1":[{"t":"table","title":"재무보고의 이용자와 중간보고","head":["구분","내용"],"rows":[["주요이용자","정보를 직접 요구할 수 없어 일반목적재무보고서에 의존해야 하는 현재 및 잠재적 투자자, 대여자와 그 밖의 채권자이다 · 경영진은 필요한 재무정보를 내부에서 구할 수 있으므로 일반목적재무보고서에 의존할 필요가 없다"],["일반목적재무보고서","이용자가 필요로 하는 모든 정보를 주지 않으며 기업가치를 보여 주는 것이 아니라 이용자가 가치를 추정하는 데 도움이 되는 정보를 준다"],["중간재무보고서의 구성","최소한 요약재무상태표, 요약포괄손익계산서, 요약자본변동표, 요약현금흐름표, 선별적 주석을 포함한다 · 포괄손익계산서는 당해 중간기간과 누적기간을, 자본변동표·현금흐름표는 누적기간만 직전 연도 동일기간과 비교한다"],["중간보고의 중요성","중요성은 해당 중간기간의 재무자료로 판단한다 · 최종 중간기간에 추정금액이 중요하게 바뀌었는데 별도 보고를 하지 않으면 그 성격과 금액을 연차재무제표 주석에 공시한다"],["보고기간후사건","보고기간 후에 선언한 배당은 보고기간말의 부채가 아니다 · 발행승인일 후 사건은 반영하지 않으므로 발행승인일과 승인자를 공시한다"]]},{"t":"table","title":"질적특성","head":["항목","내용"],"rows":[["근본적 질적특성","목적적합성과 표현충실성이다"],["목적적합한 정보","예측가치·확인가치를 가지며 이용자가 쓰지 않거나 이미 알고 있어도 의사결정에 차이를 줄 수 있다"],["중요성","해당 기업에 특유한 측면의 목적적합성이고, 질적특성은 재무제표뿐 아니라 그 밖의 방법으로 제공되는 재무정보에도 적용된다"],["충실한 표현","서술이 완전하고 중립적이며 오류가 없는 것이다 · 오류가 없다는 것은 모든 면에서 완벽하게 정확하다는 뜻이 아니라 서술에 오류나 누락이 없고 금액 산출 절차가 오류 없이 선택·적용되었다는 뜻이다"],["표현충실성과 목적적합성","표현충실성만으로 유용한 정보가 되지 않으며 목적적합성과 함께 있어야 한다"],["보강적 질적특성","비교가능성·검증가능성·적시성·이해가능성이며 이를 적용하는 것은 규정된 순서를 따르지 않는 반복적인 과정이다 · 두 방법이 똑같이 목적적합하고 충실하게 표현하면 그중 하나를 고르는 데 쓰인다"],["원가","재무보고로 제공될 수 있는 정보에 대한 포괄적 제약요인이다"]]},{"t":"table","title":"재무제표 요소와 측정기준","head":["구분","내용"],"rows":[["정의 충족","자산·부채·자본의 정의 충족 여부는 법률적 형식이 아니라 거래의 실질과 경제적 현실로 판단하며 미래에 자산을 취득하겠다는 경영진의 의사결정만으로는 현재의무가 생기지 않는다"],["인식","자산·부채는 목적적합한 정보와 충실한 표현을 모두 제공할 때 인식한다"],["제거","자산은 통제를 상실할 때, 부채는 현재의무를 더 이상 부담하지 않을 때 제거한다"],["역사적 원가","손상·손실부담 외에는 가치 변동을 반영하지 않는다"],["공정가치","취득·처분 거래원가를 모두 반영하지 않는다"],["현행원가","측정일에 지급할 대가와 그날의 거래원가를 포함한다"],["사용가치·이행가치","취득 거래원가는 빼고 처분·이행 때 생길 거래원가의 현재가치는 포함하며 이행가치는 부채가 이행될 경우에 특히 예측가치를 가진다"]]},{"t":"table","title":"보고기업과 표시 원칙","head":["구분","내용"],"rows":[["결합재무제표","지배-종속관계로 모두 연결되지 않은 둘 이상 실체로 이루어진 보고기업의 재무제표는 결합재무제표이다"],["계속기업","청산하거나 거래를 중단하려는 의도가 있으면 계속기업과 다른 기준으로 작성하고 그 기준을 기술한다 · 상당 기간 이익을 내고 재무자원을 확보한 기업은 자세한 분석 없이 계속기업 가정이 적절하다고 결론 내릴 수 있다"],["상계와 재분류","자산과 부채, 수익과 비용은 기준이 요구하거나 허용하지 않는 한 상계하지 않고 표시나 분류를 바꾸면 실무적으로 적용할 수 없는 경우가 아닌 한 비교금액도 재분류한다"],["유동부채","보고기간말 이전에 약정을 위반해 즉시 상환 요구가 가능한 채무는 보고기간 후 대여자가 상환을 요구하지 않기로 합의해도 유동부채이다 · 보고기간 후 12개월 이내 결제일이 오는 금융부채는 보고기간 후 장기 차환 약정이 있어도 유동부채이다"],["이연법인세자산(부채)","유동으로 분류하지 않는다"],["유동자산","정상영업주기 안에 실현되는 재고자산·매출채권은 12개월을 넘어도 유동자산이다"]]}],"2":[{"t":"table","title":"현금및현금성자산과 은행계정조정","head":["구분","내용"],"rows":[["현금성자산","큰 거래원가 없이 확정된 금액의 현금으로 바꾸기 쉽고 가치변동 위험이 경미한 자산으로, 보통 취득일부터 만기가 3개월 이내인 것이다 · 만기 기준은 보고기간말이 아니라 취득일부터 센다"],["분류","선일자수표는 매출채권, 우표·수입인지는 선급비용으로 분류한다"],["은행계정조정","회사 잔액과 은행 잔액을 각각 고쳐 같은 정확한 잔액에 맞춘다"],["은행 잔액 조정","기발행미인출수표와 은행 미기입 예금은 은행 잔액을 조정한다"],["회사 잔액 조정","회사가 모르는 추심어음·이자·수수료·부도수표는 회사 잔액을 조정한다"]]},{"t":"table","title":"매출채권 손상과 받을어음 할인","head":["구분","내용"],"rows":[["매출채권 손상","매출채권은 기대신용손실로 손실충당금을 설정하고, 유의적인 금융요소가 없는 매출채권은 항상 전체기간 기대신용손실로 측정한다 · 기말에 필요한 충당금과 장부상 충당금의 차이를 손상차손(환입)으로 인식하며 회수불능 확정 시 충당금과 상계해 제각한다"],["만기금액","액면에 만기까지의 표시이자를 더한 금액이다"],["할인액","만기금액에 할인율과 남은 기간을 곱한 금액이다"],["현금 수취액","만기금액에서 할인액을 뺀 금액이며 제거 조건을 충족하면 할인일의 장부금액(액면+경과이자)과 수취액의 차이가 처분손익이다"],["계산 예","액면 2,400,000원, 연 10%, 4개월 만기 어음을 2개월 보유 후 연 15%로 할인하면 만기금액 2,480,000원, 할인액 62,000원, 수취액 2,418,000원이다 · 할인일 장부금액 2,440,000원과의 차이 22,000원이 처분손실이고, 이자수익 40,000원과 합한 당기순이익 영향은 18,000원 증가이다"]]},{"t":"vs","title":"채권 양도의 제거 여부","cols":[{"name":"위험과 보상의 대부분을 이전","items":["채권을 양도하면서 소유에 따른 위험과 보상의 대부분을 이전하면 채권을 제거하고 처분손익을 인식한다"]},{"name":"위험과 보상의 대부분을 보유","items":["제거하지 않고 받은 현금을 차입금(담보부 차입)으로 인식한다","상환청구권이 있는 할인은 대체로 위험을 보유한 것이어서 차입거래로 처리한다"]}]}],"3":[{"t":"vs","title":"기말재고에 더하는 항목과 빼는 항목","cols":[{"name":"기말재고에 더함","items":["선적지인도조건으로 사서 운송 중인 상품, 미판매 적송품, 매입의사 표시 전 시송품, 담보로 맡긴 재고","도착지인도조건으로 판매해 운송 중인 상품과 선적지인도조건 판매라도 아직 선적 전인 상품도 판매자 재고이다","재구매 약정·재매입 콜옵션이 살아 있는 판매는 금융약정이라 원가를 재고에 넣고, 콜옵션이 행사 없이 소멸하면 판매로 확정된다"]},{"name":"기말재고에서 뺌","items":["수탁받아 창고에 있는 상품은 위탁자 소유이므로 실사금액에서 뺀다","도착지인도조건으로 매입해 운송 중인 상품은 아직 판매자 소유이다","할부판매처럼 대금을 나누어 받는 판매는 인도 시점에 판매가 끝나 재고가 아니다"]}]},{"t":"table","title":"시송품·적송품과 단위원가","head":["구분","내용"],"rows":[["시송품 원가","시송품이 판매가로 주어지면 판매가에 (1-매출총이익률)을 곱해 원가로 바꾼다"],["적송품 원가","적송품은 수탁자가 팔지 않은 비율만큼 위탁자 재고이고, 수탁자가 판 부분은 위탁자 매출원가가 된다"],["개별법","상호 교환할 수 없는 항목과 특정 프로젝트별 재화·용역에 쓴다"],["선입선출법·가중평균법","그 밖에는 선입선출법이나 가중평균법을 쓴다 · 성격과 용도가 유사한 재고자산에는 같은 방법을 써야 하고, 지역별 위치나 과세방식이 다르다는 이유만으로 다른 방법을 쓸 수 없다"],["선입선출법","계속기록법과 실지재고조사법의 매출원가가 같다"],["평균법","계속기록법(이동평균)과 실지재고조사법(총평균)의 결과가 다르다"]]},{"t":"table","title":"감모손실과 저가법","head":["구분","내용"],"rows":[["감모손실","(장부수량-실제수량)×단위원가이다"],["평가손실","실제수량×(단위원가-순실현가능가치)이다 · 감모를 먼저 반영한 뒤 남은 실제수량에 저가법을 적용한다"],["손실의 처리","비정상 감모는 기타비용, 정상 감모와 평가손실은 매출원가에 넣는 방식이 기출의 기본 설정이다"],["저가법 적용 단위","항목별 적용이 원칙이고 서로 비슷하거나 관련된 항목은 조별로 묶을 수 있으며 총계 기준은 허용되지 않는다"],["환입","순실현가능가치가 회복되면 최초 장부금액(원가)을 한도로 환입하고 매출원가에서 차감한다 · 기초 평가충당금이 있으면 기말 필요액과의 차이만 손실 또는 환입으로 인식한다"]]},{"t":"table","title":"순실현가능가치와 원재료","head":["구분","내용"],"rows":[["순실현가능가치","정상적인 영업과정의 예상 판매가격에서 완성원가와 판매비용을 뺀 기업특유의 가치이며 시장참여자 관점의 공정가치와 다르다"],["계산","확정판매계약 이행분은 계약가격, 계약 수량을 넘는 초과분은 일반 판매가격으로 계산한다"],["원재료의 감액","원재료를 투입한 제품이 원가 이상으로 팔릴 것으로 예상되면 원재료 가격이 내려도 감액하지 않는다 · 원재료 가격 하락으로 제품 원가가 순실현가능가치를 넘을 것으로 예상될 때만 원재료를 감액하며 이때 원재료의 현행대체원가가 순실현가능가치의 최선의 측정치가 될 수 있다"],["전환원가","고정·변동 제조간접원가의 체계적 배부액이 들어간다"],["저가법 제외","일반상품 중개기업이 순공정가치로 측정하는 재고자산에는 저가법을 적용하지 않는다"],["농림어업 수확물","생물자산에서 수확한 농림어업 수확물은 수확시점의 순공정가치로 최초 인식하며 이 금액이 재고자산의 원가가 된다"]]}],"4":[{"t":"table","title":"취득원가와 교환","head":["구분","내용"],"rows":[["취득원가","구입가격과 함께 설치장소 준비원가·설치원가처럼 자산을 사용 가능한 상태로 만드는 원가가 들어간다"],["신용기간 초과","대금 지급이 일반적인 신용기간을 넘으면 현금가격상당액(현재가치)이 원가이고 차액은 이자비용으로 나누어 인식한다"],["일괄 취득","토지와 건물을 일괄 취득하면 상대적 공정가치 비율로 원가를 나누고 토지는 상각하지 않는다"],["상업적 실질이 있는 교환","제공한 자산의 공정가치에 지급한 현금을 더해 원가로 하고, 취득한 자산의 공정가치가 더 명백하면 그 금액을 쓴다"],["상업적 실질이 없는 교환","제공한 자산의 장부금액이 원가이다"],["제거손익","순매각금액에서 장부금액을 뺀 금액이고, 손상된 자산에 대한 제3자 보상금은 받을 권리가 생길 때 당기손익으로 인식한다"]]},{"t":"table","title":"후속원가와 재평가모형","head":["구분","내용"],"rows":[["후속원가","인식기준을 충족한 후속원가는 장부금액에 더하고 일상적 수선유지비는 비용이다"],["추정의 변경","감가상각방법·잔존가치·내용연수는 적어도 매 회계연도말 재검토하며 바꾸면 회계추정의 변경으로 전진 처리한다"],["계산 예","장부금액 80,000원에 수선비 30,000원을 자산화하고 잔존내용연수 10년 연수합계법으로 바꾸면 첫해 상각비는 110,000×10/55=20,000원이다"],["재평가 증가","재평가로 장부금액이 늘면 기타포괄손익(재평가잉여금)으로 인식하되 전에 당기손실로 인식한 감소분까지는 당기이익으로 먼저 인식한다"],["재평가 감소","장부금액이 줄면 재평가잉여금 잔액까지 기타포괄손실로 줄이고 넘는 부분은 당기손실이다"],["재평가 후 상각","재평가금액에서 잔존가치를 빼고 잔존내용연수로 나누어 상각한다"],["재평가잉여금의 대체","자산을 제거할 때 이익잉여금으로 대체할 수 있고, 사용하는 기간에 일부를 대체하는 방법도 고를 수 있다 · 사용 중 대체액은 재평가 후 상각액과 원가 기준 상각액의 차이이며 자본 안의 이동이어서 당기손익과 기타포괄손익에 영향이 없다 · 당기손익으로 재분류하지 않는다"]]},{"t":"table","title":"손상과 환입","head":["구분","내용"],"rows":[["회수가능액","순공정가치와 사용가치 중 큰 금액이고 장부금액이 이보다 크면 차이를 손상차손으로 인식한다 · 손상 후에는 줄어든 장부금액을 잔존내용연수로 상각한다"],["환입","손상이 없었다면 되었을 장부금액을 한도로 하며 손상 후 장부금액 580,000원, 한도 920,000원, 회수가능액 780,000원이면 환입액은 200,000원이다"],["재평가모형 자산의 손상","먼저 공정가치로 재평가한 뒤 회수가능액과 비교한다 · 손상차손은 그 자산의 재평가잉여금을 먼저 줄이고(기타포괄손실) 남은 금액만 당기비용이다"],["현금창출단위 손상","배분된 영업권을 먼저 줄이고 남은 금액을 다른 자산에 장부금액 비율로 나눈다 · 개별 자산은 순공정가치·사용가치·0 중 가장 큰 금액 아래로 줄이지 않으며 한도에 걸린 몫은 나머지 자산에 다시 나눈다"],["영업권 손상차손","환입하지 않는다"]]},{"t":"table","title":"매각예정비유동자산","head":["구분","내용"],"rows":[["분류 요건","현재 상태로 즉시 매각할 수 있고 매각 가능성이 매우 높으며 계획이 확약되어야 매각예정으로 분류하고, 경영자의 매각 의도만으로는 부족하다"],["측정","장부금액과 순공정가치 중 작은 금액으로 측정하고 상각을 멈추지만 처분자산집단 부채의 이자·비용은 계속 인식한다"],["보고기간 후 충족","분류 요건이 보고기간 후에 충족되면 그 기간 재무제표에서는 매각예정으로 분류하지 않는다"],["손상차손 배분","처분자산집단 손상차손은 영업권 다음 1036호 적용 대상 비유동자산에 배분한다"]]}],"5":[{"t":"table","title":"차입원가 자본화","head":["구분","내용"],"rows":[["자본화 개시","적격자산 지출과 차입원가가 발생하고 자산을 준비하는 활동을 시작하면 자본화를 개시하며 착공 전 인허가를 얻는 활동도 준비활동에 들어간다"],["자본화 중단","공사가 잠시 멈추어도 그동안 상당한 기술·관리활동이 진행되면 자본화를 중단하지 않는다"],["자본화 종료","자산이 의도한 용도로 쓸 수 있는 상태가 되면 자본화를 끝낸다"],["연평균지출액","지출액에 자본화 기간 중 그 지출이 묶인 개월 수 비율을 곱해 더한다 · 같은 날 받아 공사에 쓴 정부보조금은 지출액에서 뺀다"],["전기 자본화 차입원가","전기에 자본화한 차입원가를 다음 해 평균지출에 넣을지는 문제의 가정을 따른다"],["특정차입금","자본화 기간의 이자비용에서 그 자금을 일시 투자해 번 수익을 뺀 금액을 자본화한다 · 특정차입금이 부담하는 평균지출은 차입금×기간에서 일시 투자된 금액×투자기간을 뺀 금액이다"],["일반차입금","자본화이자율은 일반차입금 이자비용 합계를 일반차입금 연평균 잔액으로 나눈 값이다 · (평균지출액-특정차입금 사용분)에 이 이자율을 곱해 자본화하되 그 기간 일반차입금에서 실제 발생한 이자비용을 넘지 못한다 · 예를 들어 이자 200,000원과 40,000원, 연평균 잔액 2,500,000원이면 이자율은 9.6%이다"]]},{"t":"table","title":"정부보조금","head":["구분","내용"],"rows":[["정부 저리·무이자 차입금","시장이자율보다 낮은 정부 차입금은 시장이자율로 할인한 현재가치로 인식하고 받은 금액과의 차이를 정부보조금으로 본다"],["계산 예","400,000원 4년 무이자 차입금(8%, 현가계수 0.7350)이면 부채 294,000원, 보조금 106,000원이다 · 차입금은 이후 유효이자율로 이자비용을 인식한다"],["자산 관련 보조금 표시","자산에서 차감하는 방법과 이연수익으로 표시하는 방법 중 고를 수 있다 · 두 방법의 매년 당기손익 영향은 같지만 처분 시에는 자산차감법은 처분손익에, 이연수익법은 남은 이연수익을 수익으로 넘기므로 처분손익 금액이 다르다"],["의무 매입 공채","자산 취득을 위해 공정가치보다 비싸게 의무 매입한 공채의 차액은 자산의 원가에 더한다"]]},{"t":"table","title":"투자부동산의 분류와 측정","head":["구분","내용"],"rows":[["투자부동산","운용리스로 제공할 목적의 미사용 건물과 사용권자산으로 보유하며 운용리스로 제공하는 건물은 투자부동산이다 · 부수 용역이 경미하면 투자부동산이다"],["자가사용부동산","소유자가 직접 경영하는 호텔은 용역이 유의적이어서 자가사용부동산이다 · 지배기업이 종속기업 본사로 리스한 건물은 연결재무제표에서 자가사용부동산이다"],["최초 측정","거래원가를 포함한 원가로 측정하고 계획된 사용수준 도달 전 운영손실은 원가에 넣지 않는다"],["공정가치모형","감가상각 없이 공정가치 변동을 당기손익에 반영하고, 시장 거래가 줄어도 처분·대체 전까지 계속 공정가치로 측정한다"],["모형 변경","원가모형에서 공정가치모형으로 바꾸는 것은 회계정책 변경이므로 소급 적용한다"]]},{"t":"table","title":"계정대체","head":["대체","처리"],"rows":[["자가사용부동산 → 공정가치모형 투자부동산","대체일 공정가치와 장부금액의 차이를 유형자산 재평가처럼 처리해 증가분은 재평가잉여금(기타포괄이익)이 된다"],["재고자산·자가건설 → 공정가치모형 투자부동산","재고자산을 공정가치모형 투자부동산으로 바꾸거나 자가건설 투자부동산이 완공되면 차이는 당기손익이다"],["공정가치모형 투자부동산 → 자가사용·재고","대체일 공정가치가 새 원가이다"]]}],"6":[{"t":"table","title":"무형자산의 정의와 인식","head":["구분","내용"],"rows":[["무형자산","식별가능성(분리가능하거나 계약·법적 권리에서 발생), 통제, 미래경제적효익을 갖춘 비화폐성자산이다"],["통제","보통 법적 권리에서 나오지만 법적 집행가능성이 통제의 필요조건은 아니다"],["비계약적 고객관계","법적 보호가 없는 비계약적 고객관계도 사업결합 밖에서 교환된 거래가 있으면 분리가능하고 통제한다는 증거가 되어 정의를 충족한다"],["인식 조건","개별 취득 무형자산과 사업결합으로 취득한 무형자산은 미래경제적효익의 유입 가능성 조건을 항상 충족한 것으로 본다"],["유입 가능성","내용연수 동안의 경제 상황에 대한 시장참여자가 아닌 경영자의 최선의 추정을 반영한 합리적 가정으로 평가하고, 최초 인식 시점의 증거 중 외부 증거에 비중을 더 둔다"],["최초 측정","최초에 공정가치가 아니라 원가로 측정하고, 사업결합으로 취득한 무형자산의 원가는 취득일 공정가치이다 · 의도한 방식으로 운용될 수 있는 상태가 되면 원가 집계를 멈추므로 사용하거나 재배치하는 데 드는 원가는 장부금액에 넣지 않는다"],["정부보조 취득","자산과 보조금을 공정가치로 인식하거나 명목금액에 직접 관련 지출을 더한 금액으로 인식한다"]]},{"t":"table","title":"연구·개발과 내부 창출","head":["구분","내용"],"rows":[["연구단계","지출은 발생 즉시 비용이고, 연구결과를 최종 선택·응용하는 활동도 연구단계이다 · 연구단계와 개발단계를 구분할 수 없으면 모든 지출을 연구단계에서 발생한 것으로 본다"],["개발단계","지출은 기술적 실현가능성·완성 의도·사용 또는 판매 능력 등 인식요건을 모두 충족할 때부터 자산이 된다"],["내부 창출 영업권","원가를 신뢰성 있게 측정할 수 없고 식별가능한 자원이 아니어서 자산이 아니다"],["내부 창출 브랜드 등","내부적으로 창출한 브랜드·제호·출판표제·고객목록과 이와 비슷한 항목도 무형자산으로 인식하지 않는다"],["시제품","연구개발로 시제품 같은 물리적 형체가 생겨도 물리적 요소는 그 지식에 부수적인 것으로 본다"],["내부 창출 무형자산의 원가","재료원가·용역원가, 창출에 든 종업원급여, 법적 권리 등록 수수료, 창출에 쓰인 특허권·라이선스 상각비는 원가에 들어간다"],["원가가 아닌 것","무형자산을 운용하는 직원의 교육훈련 지출과 일반관리원가는 원가가 아니라 비용이다 · 이미 비용으로 인식한 지출은 나중에 무형자산 원가로 되살리지 않는다"]]},{"t":"table","title":"무형자산의 상각과 손상","head":["구분","내용"],"rows":[["유한 내용연수의 상각","효익이 소비되는 형태를 반영해 상각하고 그 형태를 신뢰성 있게 정할 수 없으면 정액법을 쓴다 · 쓰지 않게 되어도 상각을 멈추지 않으며 완전히 상각하거나 매각예정으로 분류할 때 멈춘다"],["잔존가치","0으로 보되 제3자의 구입 약정이나 활성시장이 있으면 잔존가치를 인정한다"],["비한정 내용연수","상각하지 않고 매년, 그리고 손상징후가 있을 때 손상검사를 한다 · 비한정이라는 평가가 계속 타당한지 매 회계기간 검토하고, 유한으로 바꾸면 회계추정의 변경이며 이는 손상징후에 해당한다"],["계산 예","개발비 3,500,000원(내용연수 20년, 정액법)이 10월 1일부터 사용 가능하면 첫해 상각비는 3개월분 43,750원이고 다음 해 말 장부금액은 3,281,250원이다 · 이때 회수가능액이 2,000,000원이면 손상차손 1,281,250원을 인식한다"],["박토활동자산","노천광산 박토활동자산은 다른 방법이 더 적절하지 않으면 생산량비례법으로 상각한다"]]}],"7":[{"t":"table","title":"금융자산의 분류","head":["구분","내용"],"rows":[["분류 기준","금융자산은 사업모형과 계약상 현금흐름 특성 두 가지로 분류한다"],["상각후원가(AC)","원리금만 받는 현금흐름이면서 수취 목적이면 상각후원가(AC)이다"],["기타포괄손익-공정가치(FVOCI)","수취와 매도를 함께 하면 기타포괄손익-공정가치(FVOCI)이다"],["당기손익-공정가치(FVPL)","그 밖에는 당기손익-공정가치(FVPL)이다"],["FVPL 지정","회계불일치를 없애거나 줄이면 최초 인식 때 FVPL로 지정할 수 있고 이 지정은 취소할 수 없다"],["지분상품의 FVOCI 선택","단기매매 목적이 아닌 지분상품은 최초 인식 때 공정가치 변동을 기타포괄손익으로 표시하도록 선택할 수 있고 이후 취소할 수 없다 · 이 지분상품은 손상을 인식하지 않고 처분해도 기타포괄손익누계액을 당기손익으로 재분류하지 않으며 이익잉여금으로 대체할 수 있다 · 배당은 당기손익이다"]]},{"t":"table","title":"범주별 손익과 손상","head":["구분","내용"],"rows":[["최초 측정","금융자산은 공정가치에 거래원가를 더해 최초 측정하지만 FVPL 금융자산의 거래원가는 즉시 비용이다"],["FVPL 채무상품","표시이자와 공정가치 변동이 모두 당기손익이다"],["FVOCI 채무상품","유효이자율로 계산한 이자수익만 당기손익이고 공정가치와 상각후원가의 차이는 기타포괄손익이다 · 처분하면 기타포괄손익누계액을 당기손익으로 재분류하므로 매 기간과 처분 시 당기손익이 AC로 분류했을 때와 같고 자본총액만 다르다"],["손실충당금","신용위험이 유의적으로 늘지 않았으면 12개월 기대신용손실, 늘었으면 전체기간 기대신용손실로 측정한다"],["신용손상","새로 추정한 현금흐름을 당초 유효이자율로 할인해 상각후원가를 다시 구하며 현행 시장이자율은 쓰지 않는다 · 장부 965,268원 사채의 예상 현금흐름이 1년 뒤 원금 1,000,000원뿐이면(10%) 826,400원으로 줄어 손상차손은 138,868원, 다음 해 이자수익은 82,640원이다"],["신용손상 자산의 이자수익","총장부금액이 아닌 상각후원가(손실충당금 차감 후)에 유효이자율을 곱한다"],["손상 이후","추정 현금흐름이 좋아지면 다시 당초 유효이자율로 할인해 손상차손환입을 인식한다 · FVOCI 채무상품의 손상차손과 환입도 당기손익이며 회수를 합리적으로 예상할 수 없으면 총장부금액을 직접 줄인다"]]},{"t":"table","title":"계약상 현금흐름의 변경과 재분류","head":["구분","내용"],"rows":[["제거 조건 불충족 변경","새 현금흐름을 당초 유효이자율로 할인한 금액으로 총장부금액을 다시 계산하고 차이를 변경손익으로 당기손익에 인식한다 · 변경 때 부담하거나 받은 수수료는 장부금액에 반영해 남은 기간 유효이자율로 나누어 인식한다"],["제거 조건 충족 변경","기존 자산을 제거하고 새 자산을 시장이자율로 할인한 공정가치로 인식한다"],["재분류","채무상품은 사업모형을 바꿀 때만 재분류하고, 재분류일은 변경 후 첫 보고기간의 첫날이며 항상 전진 적용한다"],["AC → FVPL","공정가치와의 차이를 당기손익으로 넘긴다"],["FVOCI → FVPL","기타포괄손익누계액을 당기손익으로 넘긴다"],["FVOCI → AC","처음부터 AC였던 것처럼 측정한다"],["사업모형 변경이 아닌 것","특정 자산에 대한 의도 변경·시장의 일시적 소멸·부문 간 이전은 사업모형 변경이 아니다"]]},{"t":"table","title":"금융자산의 제거","head":["구분","내용"],"rows":[["위험과 보상","위험과 보상의 대부분을 이전하면 제거하고 대부분을 보유하면 계속 인식한다"],["보유로 보는 경우","확정가격이나 매도가격에 이자를 더한 금액으로 재매입하는 매도, 신용손실을 보증한 매도는 보유이다"],["이전으로 보는 경우","재매입 시점 공정가치로 재매입할 권리는 이전이다"],["둘 다 아닐 때","양수자가 자산을 일방적으로 매도할 실질적 능력이 있는지로 통제를 판단해 통제를 잃었으면 제거하고 통제하면 지속적으로 관여하는 정도까지 계속 인식한다"],["일부 양도","금융자산 일부만 제거하면 양도 전 장부금액을 계속 인식하는 부분과 제거하는 부분에 양도일의 상대적 공정가치로 나눈다"],["관리용역","전체를 제거하면서 수수료를 받고 관리용역을 맡으면 관리용역자산(수수료가 적정 보상보다 많을 때)이나 관리용역부채(부족할 때)를 인식한다 · 양도로 새로 얻은 금융자산이나 새로 진 부채는 공정가치로 인식한다"]]}],"8":[{"t":"table","title":"사채의 발행가액과 이자비용","head":["구분","내용"],"rows":[["발행가액","표시이자와 원금을 발행일 시장이자율로 할인한 현재가치이고, 표시이자율이 시장이자율보다 낮으면 할인발행이다"],["이자비용","기초 장부금액에 유효이자율을 곱한 금액이며 표시이자와의 차이가 상각액이다 · 할인발행이면 장부금액이 매년 늘어 이자비용도 매년 커진다"],["유효이자율 역산","둘째 해 이자비용에서 첫해 이자비용을 뺀 금액은 첫해 상각액에 유효이자율을 곱한 값이다 · 이자비용이 148,420원과 152,400원, 표시이자가 120,000원이면 첫해 상각액은 28,420원이고 유효이자율은 3,980÷28,420=14%이다"]]},{"t":"table","title":"사채발행비와 이자지급일 사이 발행","head":["구분","내용"],"rows":[["사채발행비","상각후원가 측정 금융부채는 사채발행비를 발행금액에서 빼므로 순발행금액이 줄고 유효이자율은 시장이자율보다 높아진다 · 이때 유효이자율은 순발행금액과 미래현금흐름을 일치시키는 이율로 새로 구한다"],["FVPL 금융부채","당기손익-공정가치 측정 금융부채로 분류하면 발행비는 즉시 비용이다"],["이자지급일 사이 발행","권면 발행일보다 늦게 발행하면 권면 발행일 기준 현재가치를 실제 발행일의 시장이자율로 계산하고 실제 발행일까지 유효이자를 더한 금액을 현금으로 받는다 · 이 현금에는 투자자가 미리 낸 표시이자 경과분이 들어 있으므로 사채의 순수 발행가액은 그 경과이자를 뺀 금액이다"],["조기상환","상환일까지 유효이자율로 상각한 장부금액(경과이자 제외)과 상환대가에서 표시이자 경과분을 뺀 금액을 비교해 상환손익을 당기손익으로 인식한다 · 일부만 상환하면 상환 비율만큼의 장부금액만 제거하고 남은 부분은 계속 같은 유효이자율로 이자비용을 인식한다"]]},{"t":"table","title":"조건변경","head":["구분","내용"],"rows":[["10% 기준","새 조건의 현금흐름(지급 수수료 포함)을 당초 유효이자율로 할인한 현재가치가 기존 부채 장부금액과 10% 이상 다르면 실질적 조건변경이다"],["실질적 변경","기존 부채를 제거하고 새 부채를 현행 시장이자율로 할인한 공정가치로 인식하며 차이는 당기손익이다 · 이후 이자비용은 새 부채 장부금액에 현행 시장이자율을 곱한다"],["계산 예","장부금액 965,240원 사채를 3년 연 3%로 바꾸면 당초 10%로 할인한 현재가치가 825,904원으로 14.4% 줄어 실질적 변경이다 · 새 부채는 12%로 할인한 783,854원이고 조건변경이익은 181,386원, 다음 해 이자비용은 94,062원이다"],["실질적 변경이 아닌 경우","당초 유효이자율로 할인한 현재가치로 장부금액을 조정하고 수수료는 장부금액에 반영해 남은 기간에 나눈다"]]},{"t":"table","title":"상환우선주와 자기지분상품","head":["구분","내용"],"rows":[["상환우선주","발행자가 확정일에 의무적으로 상환해야 하는 상환우선주는 금융부채이고 그 배당은 이자비용이다"],["인도할 지분상품 수량이 변동하는 계약","인도할 자기지분상품 수량이 변동하는 비파생계약도 금융부채이다"],["상환·차환 손익","금융부채의 상환·차환 손익은 당기손익이지만 지분상품의 상환·차환은 자본의 변동이다"],["자기지분상품","재취득한 자기지분상품은 자본에서 차감하고, 매입·매도·발행·소각에서 생기는 손익은 당기손익이 아니라 자본으로 직접 인식한다"],["풋가능 금융상품","금융부채에서 자본으로 재분류하면 재분류일 금융부채 장부금액으로 측정한다"]]}],"9":[{"t":"table","title":"충당부채의 인식","head":["구분","내용"],"rows":[["인식요건","과거사건의 결과로 현재의무(법적의무나 의제의무)가 있고, 자원이 유출될 가능성이 높으며 금액을 신뢰성 있게 추정할 수 있을 때 충당부채를 인식한다"],["우발부채","이 중 하나라도 충족하지 못하면 우발부채로 주석 공시하고, 유출 가능성이 아주 낮으면 공시도 하지 않는다 · 책임이 밝혀질 가능성이 높아도 배상금액을 신뢰성 있게 추정할 수 없으면 우발부채이다"],["현재의무가 아닌 지출","미래 영업활동으로 피할 수 있는 지출은 현재의무가 아니므로 3년마다 하는 항공기 정기점검 비용이나 법률이 요구하는 장치 설치 비용은 충당부채가 아니다"],["벌과금","장치를 설치하지 않아 이미 법을 어긴 데 따른 벌과금은 가능성이 높으면 충당부채이다"],["법안 제정","정화를 요구하는 법안 제정이 거의 확실해지면 그때 정화 의무가 생긴다"]]},{"t":"table","title":"원상복구와 구조조정","head":["구분","내용"],"rows":[["원상복구 의무의 발생 시점","유정 굴착장치를 건설하면 그 장치 제거와 건설로 인한 손상 복구 의무는 건설 시점에 생기지만 석유 채굴로 인한 복구 의무는 채굴할 때 생긴다"],["미지급금","금액과 시기가 확정된 의무(납부고지를 받은 벌과금 등)는 충당부채가 아니라 미지급금이다"],["구조조정충당부채","이사회가 구체적 계획을 승인한 것만으로는 의제의무가 생기지 않는다 · 구체적이고 공식적인 계획이 있고 영향을 받는 당사자에게 그 주요 내용을 공표하거나 실행에 착수해야 충당부채를 인식한다 · 보고기간말 후에 감원을 통보했다면 그 통보한 해에 인식한다"],["우발자산","재무상태표에 자산으로 인식하지 않고 유입 가능성이 높으면 주석에 공시한다 · 수익의 실현이 거의 확실해지면 더 이상 우발자산이 아니므로 그때 자산으로 인식한다 · 토지 강제수용으로 예상되는 차익도 미리 인식하지 않는다"]]},{"t":"table","title":"복구충당부채","head":["구분","내용"],"rows":[["최초 인식","복구원가의 현재가치를 충당부채로 인식하면서 같은 금액을 관련 유형자산 원가에 더하고, 이후 할인액 상각을 이자비용(금융원가)으로 인식한다"],["계산 예","복구비용 800,000원(4년, 10%)이면 충당부채는 546,400원이고 공사비 4,000,000원과 합한 자산 원가는 4,546,400원이다 · 실제 복구비가 충당부채보다 적으면 차이는 이익이다"],["추정 변경","예상 지출액이나 할인율이 바뀌면 보고기간말 새 추정 현금흐름을 새 할인율로 할인한 금액이 충당부채 잔액이 된다"],["원가모형 자산","변동분을 자산 원가에 더하거나 빼고 감소분이 장부금액을 넘으면 그 초과분은 당기손익이다"],["재평가모형 자산","부채 증가분을 재평가잉여금 잔액 안에서 줄이고 넘는 금액은 당기비용으로, 부채 감소분은 재평가잉여금(전에 비용으로 인식한 금액까지는 당기이익)으로 처리한다"]]},{"t":"table","title":"제품보증과 측정","head":["구분","내용"],"rows":[["확신유형 보증","판매 시점에 예상 보증비용을 비용과 충당부채로 인식하고 실제 지출할 때 충당부채를 줄인다"],["계산 예","판매 1,000개 중 3%가 청구되고 개당 730원이 들면 21,900원을 설정하며 그해 8,000원을 쓰면 기말 잔액은 13,900원이다"],["용역유형 보증","추가 용역을 제공하는 용역유형 보증은 별도 수행의무로 수익을 나누어 인식한다"],["측정의 원칙","충당부채는 보고기간말 의무를 이행하는 데 필요한 지출의 최선의 추정치로 측정하고, 화폐의 시간가치가 중요하면 현재가치로 측정한다"],["제3자 변제","제3자로부터 받을 변제는 받을 것이 거의 확실할 때만 별도 자산으로 인식하며 충당부채와 상계하지 않는다"]]}],"10":[{"t":"table","title":"자기주식과 자본 거래","head":["구분","내용"],"rows":[["자기주식","취득원가로 자본에서 차감하고, 재발행 때 생기는 처분이익·처분손실은 서로 상계해 자본에 남기며 포괄손익계산서에 나오지 않는다"],["소각","소각하면 자본금이 액면만큼 줄고 취득원가와 액면의 차이는 감자차손익이다"],["자본총계","취득 때 지급액만큼 줄고 재발행 때 받은 대가만큼 늘며 소각과 무상 수증은 총계를 바꾸지 않는다"],["자본총계가 변하지 않는 거래","주식배당, 이익준비금 적립, 무상증자, 자기주식 소각은 자본 항목 사이의 이동이어서 자본총계가 변하지 않는다"],["자본총계가 변하는 거래","현금배당은 자본을 줄이고 현물출자는 받은 자산의 공정가치만큼 자본을 늘린다"],["자본거래 원가","자본거래 원가와 지분상품 보유자에 대한 분배에 관련된 법인세 효과는 당기손익이 아니라 자본에 직접 반영한다"]]},{"t":"table","title":"이익잉여금 처분과 우선주 배당","head":["구분","내용"],"rows":[["이익잉여금 처분","보고기간 후 주주총회에서 결의한 처분은 그 결의가 있는 다음 회계연도에 회계처리한다"],["이익준비금","상법상 이익준비금은 자본금의 1/2에 이를 때까지 현금배당액의 1/10 이상을 적립한다"],["차기이월미처분이익잉여금","전기이월분에 당기순이익을 더하고 당기 처분액을 뺀 금액이다"],["누적적 우선주","지급하지 못한 과거 연도 배당을 먼저 받고 당기분을 받는다"],["참가적 우선주","완전참가적이면 기본 배당 뒤 남은 금액을 보통주·우선주 자본금 비율로 나누고, 부분참가적이면 정한 한도율까지만 참가한다"],["계산 예","우선주 자본금 6,000,000원(2%, 누적·5% 부분참가, 2년 연체), 보통주 10,000,000원에 1,080,000원을 배당하면 보통주 몫은 540,000원이다"]]},{"t":"table","title":"주식결제형 주식기준보상","head":["구분","내용"],"rows":[["측정","종업원에게서 받는 용역은 공정가치를 직접 추정하기 어려워 부여일의 지분상품 공정가치로 간접 측정하고, 종업원 외 거래상대방은 재화·용역을 받는 날의 그 공정가치로 측정한다"],["공정가치 산정","시장가격을 구할 수 있으면 부여조건을 반영한 시장가격을 쓰고 없을 때만 가치평가기법을 쓴다 · 지분상품 공정가치를 신뢰성 있게 추정할 수 없으면 내재가치로 측정해 결제일까지 매기 재측정하고 변동을 당기손익으로 인식한다"],["용역제공조건과 비시장 성과조건","가득될 수량·기간 추정에 반영해 매기 누적 보상원가를 다시 계산하고, 결국 충족하지 못하면 누적 인식액이 0이 되도록 환입한다"],["시장조건","부여일 공정가치에 반영하고 달성 여부와 관계없이 다른 가득조건을 충족하면 비용을 인식한다"],["가득 이후","가득된 뒤 상실되거나 행사되지 않아도 인식한 금액은 환입하지 않고 자본계정 사이의 대체만 허용된다"]]},{"t":"table","title":"조건변경·현금결제형·결제방식 선택권","head":["구분","내용"],"rows":[["조건변경","행사가격 인하처럼 공정가치를 높이는 조건변경은 당초 보상원가를 그대로 인식하면서 증분 공정가치를 변경일부터 가득일까지 추가로 인식한다"],["중도청산","가득기간 중 중도청산하면 남은 보상원가를 즉시 비용으로 인식하고, 지급액 중 청산일 공정가치까지는 자본에서 차감하며 넘는 금액은 비용이다 · 즉시 가득하는 지분상품은 부여일에 보상원가 전부를 인식한다"],["현금결제형","주가차액보상권처럼 현금으로 결제하는 보상은 부채로 인식하고 부채가 결제될 때까지 매 보고기간말과 결제일에 공정가치로 재측정하며 변동은 당기손익이다"],["현금결제형 → 주식결제형","조건변경일의 지분상품 공정가치로 자본을 인식하고 제거한 부채 장부금액과의 차이는 즉시 당기손익이다"],["거래상대방이 선택","현금과 주식 중 고를 수 있으면 부채요소와 자본요소가 있는 복합금융상품으로 보고, 자본요소는 주식결제 쪽 공정가치에서 부채요소 공정가치를 뺀 금액이다"],["기업이 선택","현금을 지급할 현재의무가 있을 때 현금결제형, 없을 때 주식결제형으로 처리한다"]]}],"11":[{"t":"table","title":"복합금융상품의 분리와 상환할증금","head":["구분","내용"],"rows":[["부채요소","표시이자와 만기 상환액(상환할증금 포함)을 같은 조건의 일반사채 시장이자율로 할인한 현재가치이다"],["자본요소","자본요소(전환권대가·신주인수권대가)는 발행금액에서 부채요소를 뺀 잔여액이다 · 이후 이자비용은 부채요소 장부금액에 그 시장이자율을 곱해 인식한다"],["상환할증금","보장수익률과 표시이자율의 차이만큼 매년 이자를 더 받은 것처럼 만기 시점까지 보장수익률로 불린 금액이다"],["계산 예","액면 1,000,000원, 표시이자 4%, 보장수익률 5%, 3년이면 10,000×(1.05²+1.05+1)=31,525원이다"],["상환할증금 미지급조건","만기 상환액은 액면뿐이다"]]},{"t":"table","title":"전환사채의 전환","head":["구분","내용"],"rows":[["자본 증가액","전환된 비율만큼 부채 장부금액이 자본으로 넘어가므로 자본 증가액은 전환일 부채 장부금액×전환비율이다"],["전환권대가","전환권대가 중 전환된 부분을 주식발행초과금으로 옮기는 것은 자본 안의 이동이다"],["주식발행초과금","증가액은 (부채 장부금액+전환권대가)×전환비율에서 발행주식 액면을 뺀 금액이다"],["계산 예","액면 1,000,000원, 표시이자 2%, 상환할증금 9.74%, 시장이자율 8%인 3년 만기 전환사채는 부채요소 922,656원, 전환권대가 77,344원이다 · 1년 뒤 부채 장부금액은 976,469원이고 60%가 액면 5,000원짜리 60주로 전환되면 주식발행초과금은 332,287원 늘어난다"]]},{"t":"table","title":"신주인수권부사채","head":["구분","내용"],"rows":[["행사","행사해도 사채가 남고 행사가격만큼 현금이 들어온다"],["상환할증금 조건","행사된 비율만큼 상환할증금을 지급하지 않게 되므로 그 장부금액이 부채에서 자본으로 넘어가고 이후 이자비용도 줄어든다"],["주식발행초과금","증가액은 납입 현금, 상환할증금 장부금액 행사분, 신주인수권대가 행사분의 합계에서 발행주식 액면을 뺀 금액이다"]]},{"t":"table","title":"조기상환과 전환 유도","head":["구분","내용"],"rows":[["조기상환","상환대가를 상환일의 부채요소 공정가치와 자본요소에 나누며 배분 방법은 발행 때와 같아야 한다 · 부채요소 공정가치는 남은 현금흐름을 상환일 일반사채 이자율로 할인해 구하고, 부채 장부금액과의 차이는 당기손익이다 · 나머지 상환대가는 자본요소의 재매입이어서 자본에서 조정한다"],["계산 예","액면 3,000,000원, 표시이자 10%, 시장이자율 12%인 3년 만기 전환사채의 1년 뒤 부채 장부금액은 2,898,686원이다 · 그날 일반사채 이자율 15%로 구한 부채요소 공정가치가 2,756,010원이면 상환이익 142,676원을 당기손익으로 인식한다"],["전환 유도 조건변경","전환을 앞당기려고 조건을 유리하게 바꾸면 바뀐 조건으로 받을 대가의 공정가치와 원래 조건 대가의 공정가치 차이를 조건변경일에 손실로 인식한다 · 전환 시 주당 200원을 더 주는 조건이면 전환될 9,000주×200원=1,800,000원이 손실이다 · 전환비율을 높이는 조건이면 늘어나는 주식 수에 조건변경일 주당 공정가치를 곱한다"]]}],"12":[{"t":"table","title":"수익 인식 5단계와 거래가격","head":["구분","내용"],"rows":[["5단계","수익은 계약 식별, 수행의무 식별, 거래가격 산정, 거래가격 배분, 수행의무 이행 시 인식의 5단계로 인식한다"],["수행의무","구별되는 재화·용역을 이전하는 약속이며 계약에 적힌 것에 한정되지 않고 사업 관행에서 생기는 암묵적 약속도 포함한다"],["수행의무가 아닌 것","고객에게 무엇을 이전하지 않는 준비 활동은 수행의무가 아니다"],["단일 수행의무","매주 반복하는 청소처럼 실질이 같은 일련의 구별되는 용역은 단일 수행의무이다"],["거래가격","변동대가가 포함되고 기댓값과 가능성이 가장 높은 금액 중 더 잘 예측하는 방법으로 추정하며 나중에 유의적으로 되돌리지 않을 가능성이 매우 높은 금액까지만 넣는다 · 제3자를 대신해 받는 금액은 빼고 비현금 대가는 공정가치로 측정한다"],["금융요소","이전 시점과 대가 지급 시점의 차이가 1년 이내로 예상되면 유의적인 금융요소를 반영하지 않는 실무적 간편법을 쓸 수 있다"],["고객에게 지급할 대가","고객에게 지급하는 대가가 고객에게서 받은 구별되는 재화·용역의 대가가 아니면 거래가격(수익)에서 차감한다 · 구별되는 용역의 대가라도 그 공정가치를 넘는 부분은 수익에서 차감하고, 공정가치를 합리적으로 추정할 수 없으면 지급액 전부를 수익에서 차감한다"]]},{"t":"table","title":"거래가격 배분과 기간에 걸친 이행","head":["구분","내용"],"rows":[["거래가격 배분","상대적 개별 판매가격 비율로 수행의무에 나누고, 계약 개시 후 개별 판매가격이 바뀌어도 다시 배분하지 않는다"],["고객충성포인트","200,000원 판매에 개별 판매가격 18,000원의 포인트를 주면 제품 183,486원, 포인트 16,514원(계약부채)으로 나눈다 · 다음 해 예상 18,000포인트 중 10,000포인트가 교환되면 16,514×10,000/18,000=9,174원을 수익으로 인식한다"],["기간에 걸친 이행 요건","고객이 효익을 동시에 얻고 소비, 고객이 통제하는 자산을 만들거나 가치를 높임, 대체 용도가 없고 완료분에 대한 집행 가능한 지급청구권을 먼저 보고, 어느 것도 아니면 한 시점에 이행하는 것으로 본다"],["진행률","산출법이나 투입법으로 측정하며 고객에게 통제를 이전하지 않는 재화는 진행률 계산에서 뺀다"],["계산 예","계약금액 5,000,000원, 진행률이 25%에서 75%로 오르고 그해 원가가 2,000,000원이면 그해 공사이익은 500,000원이다"]]},{"t":"table","title":"계약변경과 재매입약정","head":["구분","내용"],"rows":[["별도 계약","구별되는 재화가 추가되고 가격이 개별 판매가격을 반영하면 별도 계약이다"],["기존 계약 종료 후 새 계약","개별 판매가격을 반영하지 않지만 남은 재화가 이미 이전한 것과 구별되면 기존 계약을 끝내고 새 계약을 맺은 것처럼 남은 대가를 남은 수량에 다시 나눈다"],["기존 계약의 일부","구별되지 않으면 기존 계약의 일부로 보아 누적효과를 조정한다 · 범위 변경을 승인하고 가격을 아직 정하지 않았어도 계약변경은 존재한다"],["기업의 재매입 의무·권리","재매입 의무(선도)나 권리(콜옵션)가 있으면 고객이 자산을 통제하지 못하므로, 재매입가격이 원래 판매가격보다 낮으면 리스, 같거나 높으면 금융약정으로 처리하고 차이는 이자비용이다 · 콜옵션이 행사 없이 소멸하면 그때 부채를 제거하고 수익을 인식한다"],["고객의 풋옵션","재매입가격이 원래 판매가격 이상이고 예상 시장가치보다 높으면 금융약정, 행사할 경제적 유인이 유의적이지 않으면 반품권이 있는 판매로 처리한다"]]},{"t":"table","title":"반품권·보증·본인과 대리인·계약자산","head":["구분","내용"],"rows":[["반품권이 있는 판매","반품되지 않을 것으로 예상하는 부분만 수익으로 인식하고 반품 예상분은 환불부채로, 돌려받을 제품은 회수 비용과 가치 감소를 뺀 금액으로 자산(반환제품회수권)으로 인식한다"],["보증","용역유형 보증은 별도 수행의무로 거래가격을 나누고 확신유형 보증은 충당부채로 처리한다"],["본인과 대리인","가격 결정권과 재고 위험을 가진 본인은 총액으로, 대리인은 수수료 순액으로 수익을 인식하며 최소 판매 보장 수량은 인도 때 판매로 본다"],["수취채권·계약자산","대가를 받을 무조건적 권리는 수취채권이고 다른 수행의무 이행 같은 조건이 붙은 권리는 계약자산이며 취소 불가능 계약에서 지급기일이 지나면 이전 전이라도 수취채권과 계약부채를 인식한다"],["미인도청구약정","고객에게 통제가 이전되면 수익을 인식하고 보관 용역은 별도 수행의무가 된다"],["판매기준 로열티","후속 판매가 생길 때와 관련 수행의무를 이행할 때 중 늦은 때 수익으로 인식한다"]]}],"13":[{"t":"table","title":"리스의 식별·분류와 면제","head":["구분","내용"],"rows":[["리스의 식별","계약이 리스인지는 리스개시일이 아니라 계약 약정일에 판단하며 대가를 받고 식별되는 자산의 사용 통제권을 일정 기간 이전하면 리스이다"],["리스제공자의 분류","기초자산 소유에 따른 위험과 보상의 대부분을 이전하면 금융리스, 아니면 운용리스로 분류한다"],["리스이용자","이런 분류 없이 사용권자산과 리스부채를 인식한다"],["인식 면제","리스기간 12개월 이하의 단기리스와 소액 기초자산 리스는 사용권자산·리스부채를 인식하지 않고 리스료를 정액 기준 등으로 비용 처리할 수 있다"],["선택 단위","단기리스 선택은 기초자산의 유형별로, 소액 기초자산 리스 선택은 리스별로 한다 · 소액인지는 이용자의 규모와 상관없는 절대적 기준으로 판단한다"]]},{"t":"table","title":"리스이용자의 측정","head":["구분","내용"],"rows":[["리스부채","개시일에 지급되지 않은 리스료(고정리스료, 행사가 상당히 확실한 매수선택권 행사가격, 잔존가치보증에 따라 지급이 예상되는 금액)를 내재이자율로, 쉽게 산정할 수 없으면 증분차입이자율로 할인한 금액이다"],["사용권자산","리스부채에 개시일 전 선급리스료, 이용자의 리스개설직접원가, 복구원가 추정치를 더한 원가로 측정한다"],["계산 예","리스부채 2,000,000원(10%)에 매년 말 743,823원을 내면 1년 뒤 리스부채는 1,456,177원이다"],["사용권자산 상각","소유권이 이전되거나 매수선택권 행사가 상당히 확실하면 기초자산의 내용연수에 걸쳐, 아니면 리스기간과 내용연수 중 짧은 기간에 걸쳐 상각한다"],["표시","리스부채 이자비용은 감가상각비와 구분해 표시한다 · 현금흐름표에서 리스부채 원금 지급은 재무활동, 리스부채에 포함되지 않은 단기·소액·변동리스료는 영업활동이다"]]},{"t":"table","title":"리스부채의 재측정과 리스변경","head":["구분","내용"],"rows":[["수정 할인율 사용","연장선택권이나 매수선택권 행사가 상당히 확실한지 판단이 바뀌어 리스기간이나 매수 판단이 달라지면 재측정일의 수정 할인율(내재이자율을 쉽게 산정할 수 없으면 그날의 증분차입이자율)로 리스부채를 다시 계산한다"],["원래 할인율 사용","잔존가치보증 예상 지급액이나 지수·요율에 따른 리스료가 바뀌면 원래 할인율을 그대로 쓴다"],["재측정 차이","사용권자산에 더하거나 빼며 보증 예상액이 2년 뒤 50,000원으로 바뀌면(원래 8%) 50,000×0.8573=42,865원을 가산한다"],["별도 리스","하나 이상의 기초자산 사용권이 추가되어 리스 범위가 넓어지고 동시에 리스대가가 그 범위 확대의 개별 가격에 상응하게 늘어나야 별도 리스로 처리한다"],["별도 리스가 아닌 변경","두 조건 중 하나만 충족하면 별도 리스가 아니므로 변경된 리스료를 수정 할인율로 할인해 리스부채를 다시 측정한다"]]},{"t":"table","title":"리스제공자와 판매후리스","head":["구분","내용"],"rows":[["금융리스의 내재이자율","리스료와 무보증잔존가치의 현재가치 합계를 기초자산 공정가치와 제공자의 리스개설직접원가 합계와 같게 만드는 할인율이고, 그 합계가 리스순투자(금융리스채권)이다"],["이자수익","순투자에 내재이자율을 곱하며 추정 무보증잔존가치가 줄면 채권을 줄이고 즉시 손실로 인식한다 · 회수한 자산의 실제 잔존가치가 보증액에 못 미치면 그 부족분은 이용자에게서 받는다"],["제조자·판매자의 매출","기초자산 공정가치와 리스료를 시장이자율로 할인한 현재가치 중 작은 금액이며 인위적으로 낮은 이자율을 제시해도 시장이자율을 쓴다"],["제조자·판매자의 매출원가","기초자산 원가에서 무보증잔존가치의 현재가치를 뺀 금액이다 · 리스 체결에 든 원가는 리스개설직접원가에서 제외하고 개시일에 비용으로 인식한다"],["운용리스 제공자","리스료를 정액 기준으로 수익 인식하고, 리스개설직접원가는 기초자산 장부금액에 더해 리스기간에 걸쳐 비용으로 인식한다"],["판매후리스","판매에 해당하면 사용권자산을 장부금액×(리스부채÷공정가치)로 측정하고 구매자에게 이전된 권리에 대한 차익만 인식하며 판매가가 공정가치를 넘는 부분은 금융으로 본다 · 장부금액 1,200,000원 건물을 공정가치 2,000,000원에 팔고 리스부채가 1,544,340원이면 차익은 182,264원이다"]]}],"14":[{"t":"table","title":"확정기여·확정급여와 예측단위적립방식","head":["구분","내용"],"rows":[["확정기여제도","기업이 정해진 기여금만 내고 그 기간 비용으로 인식하며 종업원이 받을 급여는 기여금과 기금의 운용 효율성·투자수익에 따라 정해진다"],["확정급여제도","보험수리적 위험과 투자위험을 기업이 지므로 확정급여채무와 사외적립자산을 측정해 순액을 순확정급여부채(자산)로 표시한다"],["예측단위적립방식","확정급여채무의 현재가치와 당기근무원가는 예측단위적립방식으로 결정하고 과거근무원가에도 적용할 수 있으면 같은 방식을 쓴다 · 미래 급여를 근무기간에 나누어 귀속시키고 할인한다"],["계산 예","4년 근무 후 111,131원을 받는 종업원(할인율 10%)의 3년차 당기근무원가는 111,131×1/4÷1.1=25,257원, 이자원가는 4,592원이다"]]},{"t":"table","title":"당기손익 항목과 재측정요소","head":["구분","내용"],"rows":[["당기손익 항목","당기근무원가, 과거근무원가와 정산손익, 순확정급여부채(자산)의 순이자는 당기손익이다"],["순이자","연차보고기간 초의 순확정급여부채(자산)에 기초 할인율을 곱해 구하고, 기중 기여금 납입이나 급여 지급이 있으면 기간을 가중해 반영한다"],["과거근무원가","제도의 개정이나 축소로 생긴 확정급여채무 현재가치의 변동이며 즉시 당기손익이다"],["재측정요소","보험수리적손익, 순이자에 포함된 금액을 뺀 사외적립자산의 수익, 순이자에 포함된 금액을 뺀 자산인식상한효과의 변동으로 이루어지며 기타포괄손익으로 인식한다"],["보험수리적손익","보험수리적 가정의 변동과 경험조정에서 생긴다"],["재측정요소의 사후 처리","나중에 당기손익으로 재분류하지 않지만 이익잉여금 등 자본 안에서 대체할 수는 있다"]]},{"t":"table","title":"순확정급여부채와 자산인식상한","head":["구분","내용"],"rows":[["기말 순확정급여부채","기초 금액에 근무원가, 순이자, 재측정손실을 더하고 기여금 납입액을 뺀 금액이다"],["퇴직급여 지급","사외적립자산에서 퇴직급여를 지급하면 채무와 자산이 같이 줄어 순액은 변하지 않는다"],["계산 예","기초 2,000원, 근무원가 4,000원, 재측정손실 1,040원, 기여금 2,000원, 기말 5,180원이면 순이자 140원에서 할인율 7%가 나온다"],["자산인식상한","사외적립자산이 확정급여채무보다 많아도 순확정급여자산은 초과적립액과 자산인식상한 중 작은 금액으로 표시한다 · 순이자도 상한을 반영한 기초 순확정급여자산에 할인율을 곱해 계산하고, 상한효과 변동 중 순이자로 들어간 부분을 뺀 나머지는 재측정요소이다"],["상한 예","초과적립액 150,000원, 상한 100,000원이면 100,000원만 자산으로 인식한다"]]},{"t":"table","title":"기타장기종업원급여와 누적 유급휴가","head":["구분","내용"],"rows":[["기타장기종업원급여","퇴직급여가 아닌 기타장기종업원급여도 확정급여제도처럼 측정하지만 재측정요소를 기타포괄손익이 아니라 당기손익으로 인식한다"],["누적 유급휴가","다음 해로 이월되는 누적 유급휴가는 보고기간말 미사용 권리 때문에 추가로 지급할 것으로 예상되는 금액을 부채로 인식한다"],["후입선출 가정","당해 부여분을 먼저 쓰는 후입선출 가정에서는 이월분을 실제로 쓸 것으로 예상되는 일수만 부채가 된다"],["계산 예","연 7일 부여, 이월 3일인데 20명이 평균 9.5일을 쓸 것으로 예상되고 일당 1,500원이면 20×2.5×1,500=75,000원이다"]]}],"15":[{"t":"table","title":"일시적차이와 이연법인세 인식","head":["구분","내용"],"rows":[["일시적차이","재무상태표상 자산·부채의 장부금액과 세무기준액의 차이이며 회계이익과 과세소득의 차이로 정의하지 않는다"],["세무기준액","부채의 세무기준액은 장부금액에서 미래에 세무상 공제될 금액을 뺀 금액이고, 선수수익은 장부금액에서 미래에 과세되지 않을 수익을 뺀 금액이다"],["가산할 일시적차이","원칙적으로 모두 이연법인세부채로 인식한다"],["차감할 일시적차이 등","차감할 일시적차이, 미사용 세무상결손금, 미사용 세액공제는 그것을 쓸 수 있는 미래 과세소득이 생길 가능성이 높은 범위에서만 이연법인세자산으로 인식한다 · 예를 들어 소멸 연도의 예상 과세소득이 250,000원뿐이면 차감할 일시적차이 300,000원 중 250,000원에 대해서만 자산을 인식한다"]]},{"t":"table","title":"측정과 법인세비용","head":["구분","내용"],"rows":[["측정 세율","이연법인세는 보고기간말까지 제정되었거나 실질적으로 제정된 세법에 따라 그 차이가 소멸할 기간에 적용될 세율로 측정하므로 소멸 연도별로 세율을 달리 적용한다 · 과세소득 수준에 따라 세율이 다르면 한계세율이 아니라 소멸 기간의 평균세율을 쓴다"],["할인","이연법인세자산·부채는 현재가치로 할인하지 않는다"],["법인세비용","당기법인세(과세소득×당기세율)에 이연법인세 순자산의 감소분을 더하거나 증가분을 뺀 금액이다"],["계산 예","과세소득 1,410,000원(25%)에 이연법인세 순자산이 40,000원에서 14,400원으로 줄면 법인세비용은 352,500+25,600=378,100원이다 · 일시적차이 금액이 그대로여도 세율 변경이나 회수가능성 재검토로 이연법인세 장부금액이 바뀐다"]]},{"t":"table","title":"영구차이와 세효과","head":["구분","내용"],"rows":[["영구차이","기업업무추진비(옛 접대비) 한도초과액, 벌과금·과태료처럼 이후에도 손금이 되지 않는 항목은 당기 과세소득에만 더하고 이연법인세를 만들지 않는다"],["가산할 일시적차이의 예","미수이자처럼 나중에 과세되는 항목이다"],["차감할 일시적차이의 예","감가상각비 한도초과·충당부채 부인액이다"],["당기손익 밖의 세효과","당기손익 밖에서 인식한 항목의 법인세효과는 그 항목과 같은 곳에 인식한다"],["자본·기타포괄손익","자기주식처분이익에 대한 세금은 자본에서 빼고, 토지 재평가잉여금과 FVOCI 평가손익의 이연법인세는 기타포괄손익에서 뺀다 · 복합금융상품 자본요소의 최초 인식 때 생기는 이연법인세는 자본요소 장부금액에 직접 반영한다"]]},{"t":"table","title":"재검토와 상계","head":["구분","내용"],"rows":[["이연법인세자산의 재검토","장부금액은 매 보고기간말 검토해 과세소득 발생 가능성이 낮아지면 감액하고, 다시 가능성이 높아지면 감액분을 환입한다 · 인식하지 않았던 이연법인세자산도 매 보고기간말 다시 검토해 회수 가능성이 높아진 범위까지 인식한다"],["당기법인세 자산·부채","당기와 과거기간 법인세 중 납부하지 않은 부분은 부채, 이미 낸 금액이 내야 할 금액을 넘으면 그 초과분은 자산이다"],["상계","당기법인세자산과 부채는 법적으로 집행 가능한 상계권리가 있고 동시에 순액으로 결제하거나 동시에 실현·결제할 의도가 있을 때만 상계한다"],["이연법인세자산(부채)","유동으로 분류하지 않는다"]]}],"16":[{"t":"table","title":"회계정책의 변경","head":["구분","내용"],"rows":[["회계정책 변경의 처리","소급 적용해 비교표시되는 가장 이른 기간의 기초 이익잉여금과 비교정보를 재작성한다 · 과거 전체에 대한 누적효과를 실무적으로 정할 수 없으면 실무적으로 적용할 수 있는 가장 이른 날부터 전진 적용한다"],["회계정책 변경의 예","재고자산 단위원가 결정방법 변경, 투자부동산 원가모형에서 공정가치모형으로 바꾸는 것이 회계정책 변경의 예이다"],["정책 변경이 아닌 것","과거에 없었거나 중요하지 않았던 거래·사건에 새 회계정책을 적용하는 것과 실질이 다른 거래에 다른 정책을 적용하는 것은 회계정책 변경이 아니다"],["구분이 어려운 경우","회계정책 변경과 회계추정 변경을 구분하기 어려우면 회계추정의 변경으로 본다"]]},{"t":"table","title":"회계추정의 변경과 전기오류수정","head":["구분","내용"],"rows":[["회계추정의 변경","감가상각방법·내용연수·잔존가치, 대손 추정, 재고 진부화 추정 등의 변경은 변경한 기간과 그 이후 기간에 전진 적용한다 · 과거 재무제표는 고치지 않으며 변경일의 장부금액을 출발점으로 새 추정을 적용한다"],["전기오류수정","중요한 전기오류는 발견한 기간의 당기손익으로 처리하지 않고 소급재작성한다"],["비교표시와 기초 수정","오류가 생긴 과거 기간을 비교표시하면 그 기간 금액을 고치고, 그보다 앞서 생겼으면 비교표시되는 가장 이른 기간의 기초 자산·부채·자본을 고친다"],["예외","특정 기간 영향이나 누적효과를 실무적으로 정할 수 없는 경우만 예외이다"]]},{"t":"table","title":"자동조정 오류와 비자동조정 오류","head":["구분","내용"],"rows":[["기말재고 과대계상","그해 매출원가가 과소해 순이익이 과대가 되고, 다음 해 기초재고 과대로 다음 해 순이익이 같은 금액만큼 과소가 된다 · 그래서 두 해가 지나면 이익잉여금 오류가 저절로 사라진다"],["계산 예","20x1년 말 재고 10,000원 과대를 고치면 20x1년 순이익 10,000원 감소, 20x2년 순이익 10,000원 증가이다"],["수리비 자본화 오류","비용으로 처리할 수리비를 자산에 더했다면 발생연도 비용이 과소하고 이후 감가상각비가 과대해 매년 일부만 상쇄된다"],["수리비 계산 예","수리비 500,000원을 잔존내용연수 10년 건물에 더해 2년간 상각했다면 2년 뒤 순자산은 500,000-100,000=400,000원 과대이다"],["자본화할 지출의 비용 처리","지출액에서 그동안의 상각액을 뺀 만큼 순자산이 과소하다"]]},{"t":"table","title":"오류수정 풀이와 정책 변경의 재고자산","head":["구분","내용"],"rows":[["풀이 순서","오류마다 연도별 순이익 영향을 표로 적은 뒤 당기 이전 연도 합계를 전기이월이익잉여금 수정액으로, 당기 칸을 당기순이익 수정액으로 읽는다"],["기말수정분개 누락","선급비용을 비용 처리하지 않은 경우처럼 기말수정분개 누락도 해당 연도마다 순이익을 과대하게 만든다"],["사채이자","표시이자로만 인식했다면 유효이자와의 차이만큼 매년 이자비용이 과소하다"],["정책 변경의 매출원가 차이","당기매입은 원가흐름 가정과 상관없으므로 두 방법의 매출원가 차이는 기초재고 차이에서 기말재고 차이를 뺀 값이다"],["계산 예","가중평균법에서 선입선출법으로 바꿔 20x2년 순이익이 2,000원 늘고 20x2년 말 재고 차이가 8,000원이면 20x1년 말 재고 차이는 6,000원이다"]]}],"17":[{"t":"table","title":"기본주당이익의 분자","head":["구분","내용"],"rows":[["분자","기본주당이익의 분자는 당기순이익에서 우선주 배당 등을 뺀 보통주 귀속 당기순손익이다"],["누적적 우선주","배당결의와 관계없이 당기분 세후 배당금을 빼고(과거 연체분은 빼지 않음)"],["비누적적 우선주","당기에 결의된 배당금만 뺀다"],["상환우선주","부채로 분류한 상환우선주의 배당은 이미 이자비용으로 순이익에 들어가 있어 다시 조정하지 않는다"],["우선주 재매입","공개매수로 우선주를 재매입하면서 지급한 대가의 공정가치가 장부금액을 넘으면 그 초과액을 분자에서 빼고, 장부금액이 대가보다 크면 그 차액을 더한다"],["할증배당우선주","할인발행차금 상각액은 우선주 배당으로 보아 분자에서 뺀다"]]},{"t":"table","title":"가중평균유통보통주식수","head":["구분","내용"],"rows":[["유통일수","자기주식은 보유 기간만큼 빼고 유통일수는 주식 발행 대가를 받을 권리가 생긴 날부터 센다 · 채무상품 전환으로 발행한 주식은 최종 이자발생일 다음날부터 센다"],["무상증자·주식분할·주식병합","자원 변동이 없으므로 기초(또는 원구주 발행일)부터 있었던 것으로 소급하고 비교표시하는 모든 주당이익도 고친다"],["시가 미만 주주우선배정 유상증자","행사가격이 공정가치보다 낮은 주주우선배정 신주발행에는 무상증자 요소가 있으므로 증자 전 주식수에 조정계수(증자 직전 공정가치÷이론적 권리락 주가)를 곱한다"],["이론적 권리락 주가","(직전 공정가치×기존 주식수+발행가×신주식수)÷증자 후 주식수이다"],["계산 예","기존 800주, 직전 공정가치 1,500원, 300주를 1,000원에 7월 1일 발행하면 권리락 주가 1,363.6원, 조정계수 1.1, 가중평균주식수 990주이다"],["조건부발행보통주","모든 필요조건이 충족된 날에 발행된 것으로 보아 그날부터 기본주당이익 주식수에 넣는다 · 희석주당이익에서는 조건이 충족된 주식을 기초(또는 약정일)부터 있었던 것으로 본다 · 조건부로 재매입할 수 있는 보통주는 재매입 가능성이 없어질 때까지 보통주로 보지 않는다"]]},{"t":"table","title":"희석주당이익","head":["구분","내용"],"rows":[["잠재적보통주","기초에 전환된 것으로 보되 당기에 발행한 것은 발행일에 전환된 것으로 본다"],["희석성 판단","전환을 가정할 때 주당계속영업이익을 줄이거나 손실을 늘리는 경우에만 희석성이고, 증분주당이익이 작은 것부터 하나씩 넣어 주당이익이 더 이상 줄지 않으면 그 항목은 반희석으로 뺀다"],["반희석 예","전환사채 증분주당이익이 210원인데 그 전 단계 주당이익이 198원이면 전환사채는 반희석이다"],["옵션·신주인수권","행사된 것으로 보고 행사로 들어올 현금은 보고기간 말 시가가 아니라 평균시장가격으로 주식을 발행해 들어온 것으로 가정한다 · 무상으로 발행한 것으로 보는 주식수는 행사 주식수×(1-행사가격÷평균시장가격)이며 분자 조정은 없다"],["신주인수권 예","신주인수권 400개(행사가격 1,000원, 평균시가 1,250원)는 80주를 더하며 기중 행사분은 행사 전 기간만큼 넣는다"]]},{"t":"table","title":"전환사채·전환우선주","head":["구분","내용"],"rows":[["전환사채","분자에 세후 이자비용(이자×(1-세율))을 더하고 분모에 전환으로 발행될 주식을 더한다"],["일부 전환","기중에 일부 전환되었으면 전환일 이후 주식은 이미 기본주당이익 분모에 있으므로 전환 전 기간분만 희석 분모에 더한다"],["전환우선주","분자에 그 우선주 배당금을 다시 더한다"],["신주인수권부사채","행사해도 사채가 남으므로 이자비용을 조정하지 않는다"]]}],"18":[{"t":"table","title":"현금및현금성자산과 활동 구분","head":["구분","내용"],"rows":[["현금성자산","보고기간말이 아니라 취득일부터 만기가 3개월 이내인 단기투자자산이다"],["현금 항목 사이의 이동","현금및현금성자산을 이루는 항목 사이의 이동은 현금관리의 일부이므로 현금흐름에서 뺀다"],["현금흐름 정보","같은 거래에 서로 다른 회계처리를 적용한 영향을 없애 기업 간 영업성과의 비교가능성을 높인다"],["이자·배당","이자와 배당금의 수취, 이자 지급은 영업활동으로 하거나 각각 투자·재무활동으로 할 수 있고, 배당금 지급은 재무활동이나 영업활동으로 할 수 있으며 선택한 분류는 매기 일관되게 쓴다"],["법인세 납부","투자·재무활동과 명백히 연결되지 않는 한 영업활동이다"],["리스·유형자산","리스부채 원금 상환은 재무활동, 유형자산 취득·처분은 투자활동이다"]]},{"t":"table","title":"간접법과 이자·법인세","head":["구분","내용"],"rows":[["간접법","순이익에서 감가상각비, 사채할인발행차금 상각액 같은 비현금 비용을 더하고 유형자산처분손익처럼 투자·재무활동 손익을 없앤 뒤 영업 관련 자산·부채 증감을 반영한다"],["순액 조정","매출채권·재고자산을 손실충당금·평가충당금 차감 후 순액으로 조정하면 손상차손·평가손실은 이미 반영되었으므로 다시 더하지 않는다"],["이자 지급이 영업활동일 때","이자비용은 되돌리지 않고 미지급이자 증감과 비현금 상각액만 조정한다"],["법인세 납부액","법인세비용에서 당기법인세부채 증가액을 빼고 이연법인세부채 감소액(또는 이연법인세자산 증가액)을 더한 금액이다"],["영업에서 창출된 현금","이자·배당 수취, 이자 지급, 법인세 납부 전 금액이다"]]},{"t":"table","title":"이자 지급액과 고객·공급자 현금흐름","head":["구분","내용"],"rows":[["이자 지급액","이자비용에서 사채할인발행차금 상각액을 빼고 사채할증발행차금 환입액을 더하며 미지급이자 증가액을 뺀 금액이다"],["이자 지급액 계산 예","이자비용 48,191원, 할인차금 상각 2,349원, 할증차금 환입 3,358원, 미지급이자 증가 5,000원이면 이자 지급액은 44,200원이다"],["고객으로부터의 현금유입","매출액에서 매출채권 총액 증가분을 빼고 매출채권 관련 외환이익을 더한 뒤 제각액을 뺀 금액이다"],["제각액","기초 손실충당금에 손상차손을 더하고 기말 손실충당금을 뺀 금액이다 · 현금매출이 따로 있으면 신용매출로 매출채권 계정을 맞춘 뒤 현금매출을 더한다"],["공급자에 대한 현금유출","매입채무 계정에서 기초 잔액에 외상매입을 더하고 외화환산이익과 결제액을 빼면 기말 잔액이 되므로 이를 역산해 매입액을 구한다"],["매출원가","기초재고에 매입을 더하고 기말재고(평가충당금 차감 전)를 뺀 금액이며 기타비용으로 처리한 감모손실·평가손실은 매출원가에 넣지 않는다 · 기초재고 300,000원, 매입 791,000원, 기말재고 170,000원이면 매출원가는 921,000원이다"]]},{"t":"table","title":"투자·재무활동 역산","head":["구분","내용"],"rows":[["처분대가","유형자산 취득원가와 감가상각누계액의 기초·기말 잔액과 당기 취득·상각액으로 처분자산의 원가와 누계액을 구하고, 처분 장부금액에 처분이익을 더해 처분대가를 낸다"],["계산 예","기계장치 처분원가 80,000원, 처분분 누계액 30,000원, 처분이익 5,000원이면 처분대가는 55,000원이고 취득 100,000원과 합한 투자활동은 45,000원 유출이다"],["미지급금과 배당금","미지급금으로 남긴 취득대금은 현금유출이 아니며 배당금 지급액은 이익잉여금 증감과 당기순이익으로 역산한다"]]}],"19":[{"t":"table","title":"유의적인 영향력과 지분법","head":["구분","내용"],"rows":[["유의적인 영향력","직접 보유분과 종속기업 보유분을 합쳐 의결권의 20% 이상이면 반증이 없는 한 유의적인 영향력이 있다고 보며 투자자의 다른 관계기업이 가진 지분은 합산하지 않는다"],["다른 투자자의 과반수","다른 투자자가 과반수를 가졌다고 해서 유의적인 영향력이 반드시 없는 것은 아니다"],["잠재적 의결권","현재 행사하거나 전환할 수 있는 잠재적 의결권은 다른 기업이 보유한 것도 고려한다"],["지분법의 기본 처리","투자는 원가로 인식한 뒤 피투자자 당기순손익 중 투자자 몫은 지분법손익(당기손익), 기타포괄손익 몫은 기타포괄손익으로 장부금액에 가감한다"],["배당","피투자자에게서 받은 배당은 수익이 아니라 투자 장부금액의 감소이다"],["우선주","제3자가 가진 자본 분류 누적적 우선주가 있으면 배당결의와 관계없이 그 배당을 빼고 순손익 몫을 계산한다"]]},{"t":"table","title":"투자차액과 지분법이익 계산","head":["구분","내용"],"rows":[["영업권","취득원가가 피투자자 식별가능 순자산 공정가치의 지분보다 크면 그 차이는 영업권으로 투자 장부금액에 포함되어 상각하지 않고 별도의 손상검사도 하지 않는다"],["염가매수차익","작으면 그 차이(염가매수차익)를 취득 연도 지분법이익에 넣는다"],["공정가치 차이 조정","공정가치와 장부금액이 다른 재고자산은 판매된 비율만큼, 건물은 추가 감가상각만큼 피투자자 순이익을 줄여 지분을 계산한다"],["계산 예","취득원가 400,000원, 순자산 공정가치 1,450,000원의 30%가 435,000원이면 염가매수차익은 35,000원이다 · 순이익 150,000원에서 판매된 재고 평가차액 50,000원과 건물 추가상각 20,000원을 빼면 80,000원이고 그 30%는 24,000원이므로 지분법이익은 59,000원이다"]]},{"t":"table","title":"내부거래·현물출자·손실 한도","head":["구분","내용"],"rows":[["내부거래 미실현손익","상향거래와 하향거래 모두 미실현손익 중 투자자 지분만큼 제거해 관계기업 지분과 무관한 손익까지만 인식한다"],["손실","거래가 순실현가능가치 감소나 손상의 증거이면 하향거래 손실은 투자자가 전액 인식하고 상향거래 손실은 자기 몫을 인식한다"],["계산 예","하향 판매이익 30,000원 중 50%가 재고로 남고 지분율이 25%이면 3,750원을 지분법이익에서 뺀다"],["현물출자","상업적 실질이 있는 현물출자는 출자자산의 처분이익 중 관계기업에 대한 자기 지분에 해당하는 부분을 빼고 나머지만 인식한다 · 장부금액 20,000원 토지를 공정가치 30,000원에 출자하고 30% 지분을 받으면 처분이익 10,000원 중 70%인 7,000원만 인식한다"],["손실 인식 한도","지분법 손실이 누적되어도 관계기업 투자 장부금액은 0 아래로 내려가지 않는다 · 다만 결제 계획이 없는 무담보 장기대여금처럼 실질적으로 순투자의 일부인 항목까지는 추가로 손실을 인식하며 매출채권은 순투자가 아니다 · 그 뒤에는 법적·의제의무가 있거나 대신 지급한 범위에서만 부채를 인식한다"]]},{"t":"table","title":"지분법 중단과 공동약정","head":["구분","내용"],"rows":[["유의적인 영향력 상실","잔여 지분을 공정가치로 재측정하고 (처분대가+잔여 지분 공정가치-장부금액)을 당기손익으로 인식한다"],["기타포괄손익","지분법으로 쌓은 기타포괄손익은 피투자자가 관련 자산을 직접 처분했을 때와 같은 기준으로 처리해 FVOCI 채무상품·해외사업장 외환차이는 재분류하고 재평가잉여금은 이익잉여금으로 대체한다"],["지분 변동","관계기업과 공동기업 사이의 전환은 지분법을 계속 적용하고 재측정하지 않으며 영향력을 유지하며 지분율이 줄면 자본거래가 아니라 처분손익을 인식한다"],["공동약정","둘 이상의 당사자가 공동지배력을 갖는 약정이고, 공동지배력은 관련 활동 결정에 지배력을 공유하는 당사자 전체의 동의가 필요할 때 존재하며 모든 당사자가 공동지배력을 가질 필요는 없다"],["공동영업","자산에 대한 권리와 부채에 대한 의무를 가지면 공동영업으로 자기 몫의 자산·부채·수익·비용을 인식한다"],["공동기업","순자산에 대한 권리를 가지면 공동기업으로 지분법을 적용한다 · 별도기구가 있어도 권리·의무에 따라 둘 중 하나로 분류하며 공동지배력이 없는 참여자는 유의적인 영향력이 있으면 1028호, 없으면 1109호를 적용한다"]]}],"20":[{"t":"table","title":"사업결합의 범위와 식별가능한 자산·부채","head":["구분","내용"],"rows":[["사업","투입물과 그에 적용하는 과정으로 이루어지며 산출물은 필수 요소가 아니다"],["사업이 아닌 자산 집단","사업이 아닌 자산 집단을 사면 사업결합이 아니어서 원가를 상대적 공정가치로 나누고 영업권이나 염가매수차익을 인식하지 않는다"],["적용 범위","동일 지배 아래 기업 간 결합과 공동약정의 구성에는 1103호를 적용하지 않고, 대가를 이전하지 않아도 사업결합이 될 수 있으며 취득일은 보통 종료일이지만 그보다 이르거나 늦을 수 있다"],["취득 자산·인수 부채","취득일 공정가치로 측정하되 이연법인세·종업원급여·매각예정자산(순공정가치) 등은 예외이다"],["무형자산","집합적 노동력은 영업권에 포함하고, 법적 보호가 없어도 매각·라이선스할 수 있는 상표나 고객목록, 진행 중인 연구개발 프로젝트는 별도 무형자산으로 인식하지만 협상 중인 신규 계약은 취득일 자산이 아니다"],["다시 취득한 권리","갱신 가능성과 관계없이 남은 계약기간으로 측정하고 피취득자가 이미 인식한 영업권은 식별가능 자산에서 뺀다"],["우발부채와 리스","현재의무이고 공정가치를 신뢰성 있게 측정할 수 있으면 자원 유출 가능성이 높지 않아도 우발부채를 인식하며 이후 1037호 금액과 최초 인식액에서 누적 수익을 뺀 금액 중 큰 금액으로 측정한다 · 피취득자가 리스이용자인 리스의 유리한 조건은 사용권자산에 더하고, 피취득자가 운용리스로 제공한 자산의 불리한 조건은 그 자산의 공정가치에 반영한다 · 구조조정처럼 계획에 따라 생길 것으로 예상할 뿐 의무가 아닌 원가는 취득일 부채가 아니다"]]},{"t":"table","title":"이전대가와 영업권","head":["구분","내용"],"rows":[["이전대가","지급 현금, 발행 주식의 공정가치, 조건부대가의 취득일 공정가치를 합한 금액이다"],["취득관련원가","중개수수료·실사비·내부 관리원가 같은 취득관련원가는 비용이고 지분증권 발행원가는 자본에서 뺀다"],["단계적 취득","기존 보유 지분을 취득일 공정가치로 재측정해 이전대가에 더하고 그 차이를 당기손익(FVOCI 지분상품이면 기타포괄손익)으로 인식한다"],["영업권","이전대가와 비지배지분, 기존 보유 지분 공정가치의 합에서 식별가능 순자산 공정가치를 뺀 금액이고 음수이면 염가매수차익으로 당기이익이다"],["영업권의 처리","상각하지 않고 매년 손상검사하며 영업권 자체에는 이연법인세부채를 인식하지 않는다"],["평가차액","평가차액에는 이연법인세부채를 인식해 순자산을 줄이므로 건물 평가차액 50,000원(세율 25%)이 있으면 80% 지분의 영업권이 70,000원에서 80,000원으로 커진다"]]},{"t":"table","title":"측정기간과 조건부대가","head":["구분","내용"],"rows":[["측정기간","취득일부터 1년 이내 측정기간에 취득일 당시 사실에 대한 정보를 얻으면 잠정금액을 취득일로 소급해 고치고 영업권과 감가상각도 다시 계산한다"],["조건부대가 변동","목표 달성 여부처럼 취득일 이후 사건으로 생긴 조건부대가 변동은 영업권을 고치지 않는다"],["조건부대가의 분류","부채로 분류한 조건부대가는 공정가치 변동을 당기손익으로 인식하고 자본으로 분류한 조건부대가는 재측정하지 않는다"],["계산 예","유형자산 평가로 순자산이 100,000원 늘고 취득일 소송 결과로 조건부대가가 30,000원 늘면 영업권 220,000원은 150,000원이 된다"]]},{"t":"table","title":"지배력·연결·지분 변동","head":["구분","내용"],"rows":[["지배력","피투자자에 대한 힘, 변동이익에 대한 노출이나 권리, 힘을 사용해 그 이익에 영향을 미치는 능력을 모두 갖출 때 있다"],["힘","의결권 과반수라도 그 권리가 실질적이지 않으면 힘이 없고, 방어권만으로는 힘이 없으며 다른 당사자의 실질적 잠재적 의결권도 고려한다"],["연결 범위","종속기업 보고기간 종료일 차이는 3개월을 넘을 수 없고, 투자기업은 종속기업을 연결하지 않고 공정가치로 측정한다"],["순이익 배분","종속기업 순이익은 평가차액의 실현(재고 판매, 추가 감가상각)과 상향거래 미실현손익을 조정한 뒤 지분율로 나누고, 하향거래 미실현손익은 전액 지배기업 몫에서 뺀다"],["내부거래","내부 판매한 유형자산의 처분이익은 남은 내용연수 동안 감가상각에 따라 나누어 실현되고, 지배기업이 받은 종속기업 배당은 연결에서 제거한다 · 비지배지분이 음수가 되어도 총포괄손익을 계속 배분하며 배분 비율은 잠재적 의결권이 아닌 현재 소유지분으로 정한다"],["지배력 유지","종속기업 지분을 사고팔면 자본거래이고 그 현금흐름은 재무활동, 지배력 획득·상실에 따른 현금흐름은 투자활동이다"],["지배력 상실","종속기업 자산·부채·영업권과 비지배지분을 제거하고 받은 대가와 잔여 지분 공정가치와의 차이를 당기손익으로 인식하며 관련 기타포괄손익은 직접 처분했을 때와 같은 기준으로 재분류하거나 이익잉여금으로 대체한다"],["별도재무제표","종속·관계·공동기업 투자를 원가법, 1109호, 지분법 중 골라 처리하고 받은 배당은 받을 권리가 확정될 때 당기손익이다"]]}],"21":[{"t":"table","title":"기능통화와 외화 환산","head":["구분","내용"],"rows":[["기능통화·표시통화·외화","기능통화는 영업활동이 이루어지는 주된 경제 환경의 통화, 표시통화는 재무제표를 표시하는 통화이며 외화는 표시통화가 아니라 기능통화 이외의 통화이다"],["기능통화 변경","변경일부터 전진 적용하고 변경일 환율로 모든 항목을 환산해 비화폐성항목은 그 금액을 새 역사적원가로 삼는다"],["표시 통화","해외사업장이 없는 기업이나 별도재무제표를 작성하는 기업은 어떤 통화로도 재무제표를 표시할 수 있다"],["화폐성항목","외화거래는 거래일 환율로 처음 기록하고 보고기간말 화폐성항목(매출채권·차입금)은 마감환율로 환산해 차이를 당기손익으로 인식한다"],["역사적원가 비화폐성항목","역사적원가로 측정하는 비화폐성항목(재고자산·선수금·원가모형 토지)은 거래일 환율을 유지한다"],["공정가치 비화폐성항목","공정가치로 측정하는 비화폐성항목은 공정가치 측정일 환율을 쓰며 환율효과는 평가손익을 인식하는 곳(당기손익 또는 기타포괄손익)을 따른다"],["외화 재고자산","원가(거래일 환율)와 순실현가능가치(마감환율)를 비교해 저가법을 적용한다"]]},{"t":"table","title":"외화 환산 계산과 해외사업장","head":["구분","내용"],"rows":[["환산 예","마감환율 1,000원에서 매출채권 $200(최초 185,000원)은 환산이익 15,000원, 차입금 $150(최초 140,000원)은 환산손실 10,000원이다 · 재고자산 $160(원가 158,000원)의 순실현가능가치가 $150이면 평가손실 8,000원이고, FVOCI 지분상품의 환율효과는 기타포괄손익이며 선수금은 환산하지 않으므로 당기순이익은 3,000원 감소한다"],["외화 FVOCI 채무상품","외화 상각후원가 기준의 이자수익과 외환차이를 당기손익으로, 공정가치와 상각후원가의 차이만 기타포괄손익으로 인식한다"],["해외사업장의 표시통화 환산","자산·부채는 보고기간말 마감환율, 수익·비용은 거래일 환율(평균환율로 근사 가능), 자본금은 납입 당시 환율로 환산하고 남는 차이는 해외사업장환산차이(기타포괄손익)이다"],["환산 계산 예","순자산 $1,450(마감환율 1,000원), 자본금 $1,000(설립 시 900원), 순이익 $150(평균 940원)과 $300(평균 980원)이면 환산차이 누계는 115,000원이다"],["영업권과 공정가치 조정액","해외사업장 취득으로 생긴 영업권과 공정가치 조정액은 해외사업장의 자산·부채로 보아 마감환율로 환산한다"],["순투자 화폐성항목","해외사업장 순투자의 일부인 화폐성항목에서 생긴 외환차이는 별도재무제표나 해외사업장의 개별재무제표에서는 당기손익, 둘을 포함하는 연결재무제표에서는 기타포괄손익이다"],["해외사업장 처분","누적 외환차이를 처분손익을 인식할 때 당기손익으로 재분류한다 · 해외사업장을 포함한 종속기업을 일부 처분하면 누적 외환차이 중 비례 몫을 비지배지분으로 다시 귀속시킨다"]]},{"t":"table","title":"파생상품과 위험회피회계의 요건","head":["구분","내용"],"rows":[["파생상품","공정가치로 측정하며 계약 체결일의 선도계약 공정가치는 0이다 · 위험회피로 지정하지 않으면 평가손익을 모두 당기손익으로 인식한다"],["매도 통화선도","평가손익은 (계약 선도환율-보고기간말 잔여만기 선도환율)×외화금액이므로, ¥100,000을 9.5원에 파는 계약은 선도환율이 9.9원이 되면 40,000원 손실이고 만기 현물환율 9.4원에 결제하면 그해 50,000원 이익이다"],["위험회피회계의 요건","개시 시점에 위험회피관계와 위험관리 목적·전략을 지정·문서화하고, 대상과 수단 사이에 경제적 관계가 있으며 신용위험이 그 가치 변동을 지배하지 않고, 위험회피비율이 적절해야 한다"],["효과성","개시 시점부터 미래 전망적으로 계속 평가하고 비율 요건을 못 맞춰도 위험관리 목적이 같으면 비율을 재조정하며 자발적 중단은 허용되지 않는다"],["수단과 대상","외부 당사자와 맺은 계약만 수단이 되고 지분법 투자와 종속기업 투자는 공정가치위험회피 대상이 될 수 없으며 사업결합으로 사업을 취득하는 확정계약은 외화위험만 대상이 된다"]]},{"t":"vs","title":"공정가치위험회피와 현금흐름위험회피","cols":[{"name":"공정가치위험회피","items":["인식된 자산·부채나 확정계약의 공정가치 변동을 회피하며 수단과 대상의 평가손익을 모두 당기손익으로 인식한다(FVOCI 지분상품이 대상이면 둘 다 기타포괄손익)","확정계약을 대상으로 하면 그 공정가치 변동을 확정계약자산·부채로 인식하고 계약 이행으로 취득한 자산의 최초 장부금액에 반영한다","고정금리 차입금·대여금을 변동금리로 바꾸는 스왑, 보유 재고의 가격 하락을 막는 매도선도가 대표적이며 확정계약의 외화위험은 공정가치·현금흐름 위험회피 중 고를 수 있다"]},{"name":"현금흐름위험회피","items":["변동금리 차입금의 이자나 발생 가능성이 매우 높은 예상거래의 현금흐름 변동을 회피하며 수단 누적손익과 대상 누적변동 중 작은 금액(효과적 부분)을 현금흐름위험회피적립금(기타포괄손익)으로, 나머지를 당기손익으로 인식한다","예상 매입이 비금융자산 취득으로 이어지면 적립금을 그 자산 원가에 반영하고, 예상 매출처럼 손익에 영향을 주면 그때 당기손익으로 재분류한다","금선도 평가이익 100,000원, 대상 변동 50,000원이면 50,000원은 기타포괄손익, 50,000원은 당기이익이고, 해외사업장순투자 위험회피도 같은 방식으로 처리한다"]}]}],"22":[{"t":"table","title":"원가의 흐름","head":["구분","내용"],"rows":[["직접재료원가","기초원재료에 매입액을 더하고 기말원재료를 뺀 사용액(간접재료 제외)이다"],["당기총제조원가","직접재료원가, 직접노무원가, 제조간접원가의 합이다"],["당기제품제조원가","당기총제조원가에 기초재공품을 더하고 기말재공품을 뺀 금액이다"],["매출원가","기초제품에 당기제품제조원가를 더하고 기말제품을 뺀 금액이다"],["계산 예","원재료 기초 23,000원·매입 55,000원·기말 12,000원이면 사용액은 66,000원이고 가공원가 64,000원을 더한 당기총제조원가는 130,000원이다 · 재공품 기초 30,000원·기말 45,000원이면 당기제품제조원가는 115,000원, 제품 기초 13,000원·기말 28,000원이면 매출원가는 100,000원이다"]]},{"t":"table","title":"기본원가·가공원가와 제조원가·기간원가","head":["구분","내용"],"rows":[["기본원가(기초원가, prime costs)","직접재료원가와 직접노무원가의 합이다"],["가공원가(전환원가)","직접노무원가와 제조간접원가의 합이며 직접노무원가는 두 개념에 모두 들어간다"],["제조경비","간접재료원가·간접노무원가·공장 감가상각비 같은 제조경비는 제조간접원가이다"],["제조원가","재고자산 원가에 들어가는 재고가능원가이고 제품이 팔릴 때 매출원가가 된다"],["판매관리비","판매직·관리직 급여, 광고선전비 같은 판매관리비는 재고불능원가(기간원가)로 발생한 기간에 비용 처리한다"],["급여의 구분","공장 근로자·공장 감독자 급여는 제조원가, 본사 관리직 급여는 기간원가이다"]]},{"t":"table","title":"노무원가 역산과 원가행태","head":["구분","내용"],"rows":[["노무원가 발생액","지급액에서 기초 미지급액을 빼고 기말 미지급액을 더한 금액이다 · 지급 3,700원·기초 미지급 200원·기말 미지급 500원이면 노무원가는 4,000원이다"],["간접재료원가","재료 사용액에서 직접재료원가를 뺀 금액이고, 직접재료원가는 기본원가에서 직접노무원가를 빼서 구할 수 있다"],["변동원가","조업도에 비례해 총액이 변하고 단위당 원가는 일정하다"],["고정원가","관련범위 안에서 총액이 일정하고 단위당 원가는 조업도에 반비례한다"],["준변동원가","고정 부분과 변동 부분을 함께 가진다 · 이 구분은 관련범위 안에서만 성립한다"]]}],"23":[{"t":"table","title":"정상개별원가계산과 배부차이","head":["구분","내용"],"rows":[["개별원가계산","주문에 따라 다품종을 소량 생산할 때 작업별로 원가를 모으는 방법이다"],["정상원가계산","직접재료원가·직접노무원가는 실제원가로, 제조간접원가는 예정배부율(예상 제조간접원가÷예상 배부기준)에 실제 배부기준량을 곱해 배부한다"],["과대배부·과소배부","실제 발생액보다 배부액이 크면 과대배부, 작으면 과소배부이다"],["매출원가조정법","배부차이를 전액 매출원가에 더하거나 뺀다"],["총원가기준 비례배부법","기말재공품·기말제품·매출원가의 총원가 비율로 나눈다"],["원가요소기준 비례배부법","각 계정에 들어 있는 당기 제조간접원가 배부액 비율로 나눈다 · 과소배부는 원가를 늘리고 과대배부는 원가를 줄인다"]]},{"t":"table","title":"배부차이 계산과 역산","head":["구분","내용"],"rows":[["배부차이 계산 예","예정배부율이 기계시간당 20원이고 실제 3,800시간이면 배부액은 76,000원, 실제 82,000원이면 과소배부 6,000원이다 · 판매된 작업의 총원가가 80,000원, 전체 작업 총원가가 200,000원이면 총원가기준으로 2,400원을 매출원가에 더한다"],["예정배부율 역산","기말재공품에 든 제조간접원가 배부액을 그 작업의 직접노무원가로 나누면 직접노무원가 기준 예정배부율이 나온다"],["실제 발생액 역산","실제 발생액은 배부액에 과소배부액을 더하거나 과대배부액을 뺀 금액이다 · 당기총제조원가가 직접재료원가+직접노무원가×(1+배부율)이므로 이 식으로 직접노무원가를 역산할 수 있다"]]},{"t":"table","title":"보조부문 원가 배분","head":["구분","내용"],"rows":[["직접배분법","보조부문 간 용역 제공을 무시하고 제조부문에만 배분한다"],["단계배분법","정한 순서대로 배분하되 이미 배분을 끝낸 보조부문에는 다시 배분하지 않으므로 순서에 따라 결과가 달라진다"],["상호배분법","보조부문 사이의 용역을 모두 반영해 연립방정식으로 푸는 가장 정확한 방법이며 어느 방법이든 자기부문 사용분은 빼고 제조부문에 배분되는 총액은 같다"],["상호배분법 계산 예","자체 원가가 A부문 220,000원, B부문 180,000원이고 A 용역의 40%가 B에, B 용역의 50%가 A에 제공되면 A=220,000+0.5B, B=180,000+0.4A를 풀어 A=387,500원, B=335,000원이다 · 제조부문 C가 A 용역의 40%와 B 용역의 25%를 쓰면 C 배분액은 155,000+83,750=238,750원이다"]]},{"t":"table","title":"이중배분율","head":["방법","내용"],"rows":[["이중배분율법","변동원가는 실제 사용량을 기준으로, 고정원가는 최대(정상) 사용가능량을 기준으로 따로 배분한다"],["미배부액","고정원가를 정상조업도 기준 배부율로 실제 사용량만큼만 배부하면 남는 고정원가는 미배부액이 되어 당기비용으로 처리될 수 있다"],["단일배분율법","변동·고정을 구분하지 않고 하나의 기준으로 배분한다"]]}],"24":[{"t":"table","title":"활동기준원가계산의 구조와 원가계층","head":["구분","내용"],"rows":[["기본 구조","활동이 자원을 소비하고 제품이 활동을 소비한다는 관점에서 원가를 활동별로 모은 뒤 활동원가동인 수로 제품에 배부한다"],["사후원가계산","발생한 원가를 활동중심점별로 집계해 실제 동인 수로 배부하므로 사후원가계산 성격을 가진다"],["단위수준활동","제품 한 단위마다 일어나는 활동으로 기계 가동, 전수조사 품질검사가 있다"],["묶음수준활동","묶음(배치)마다 일어나는 원재료 구매주문, 작업준비, 표본 품질검사이다"],["제품유지활동","제품 종류별 설계·설계변경이다"],["설비유지활동","공장 관리처럼 특정 제품과 무관한 활동이다"]]},{"t":"table","title":"도입 배경과 고객수익성 분석","head":["구분","내용"],"rows":[["원가 왜곡","제조간접원가 비중이 커지고 그 안에 생산량 외의 원가동인으로 생기는 원가가 많아지면서 조업도 하나로 배부하면 원가가 왜곡된다"],["조업도 기준 배부","대량 생산 제품에 원가를 과대 배부하고 소량·복잡 제품에 과소 배부하는 경향이 있다 · 다품종 소량 생산 환경과 정보기술 발달이 도입을 뒷받침한다"],["고객수익성 분석","제품원가뿐 아니라 주문 처리·특별 서비스·고객관리 같은 판매관리비도 활동별로 모아 고객에게 배부할 수 있다"],["계산 예","재료원가에 100%를 가산해 청구하는 회사에서 고객 A가 1,400원을 청구받고 활동원가가 575원이면 이익은 1,400-700-575=125원이다 · 청구 750원, 활동원가 610원인 고객 B는 235원 손실이다"]]},{"t":"table","title":"활동별 배부율과 활동기준경영","head":["구분","내용"],"rows":[["활동별 배부율","활동원가를 그 활동의 총 원가동인 수로 나눈 값이고 제품 원가는 제품이 쓴 동인 수에 배부율을 곱해 더한다"],["계산 예","재료이동 1,512,000원을 630회로 나누면 회당 2,400원이고, 조립 7,000,000원을 1,400시간으로 나누면 시간당 5,000원이다"],["활동기준경영(ABM)","활동 분석 결과는 원가 배부뿐 아니라 고객에게 가치를 더하지 않는 비부가가치 활동을 찾아 줄이는 활동기준경영(ABM)에 쓰인다"],["원가 절감 목표","원가동인 수를 줄이면 해당 활동원가가 줄어든다는 점에서 원가 절감 목표를 활동 단위로 세울 수 있다"]]}],"25":[{"t":"table","title":"물량흐름과 평균법","head":["구분","내용"],"rows":[["종합원가계산","같은 제품을 연속 생산할 때 공정별로 원가를 모아 완성품환산량으로 나눈다"],["환산량","공정 초에 전량 투입되는 직접재료는 완성도 100%로, 공정 전반에 균등하게 발생하는 전환원가(가공원가)는 실제 완성도로 환산한다"],["물량","기초재공품+착수량=완성품+기말재공품+공손품으로 맞춘다"],["평균법","기초재공품을 당기에 착수한 것처럼 보아 기초재공품 원가와 당기 투입원가를 합해 완성품과 기말재공품 환산량 합계로 나눈다 · 기초재공품의 완성도는 계산에 쓰이지 않는다"],["평균법 계산 예","기초 2,000단위, 착수 10,000단위, 기말 4,000단위(50%)면 전환원가 환산량은 8,000+2,000=10,000단위이다"]]},{"t":"table","title":"선입선출법","head":["구분","내용"],"rows":[["선입선출법","기초재공품을 먼저 완성한다고 보아 당기 투입원가만 당기 작업량(기초분 마무리분+당기 착수·완성분+기말재공품)으로 나눈다"],["기초재공품 원가","기초재공품 원가는 전부 완성품원가에 들어간다"],["재료 환산량","공손이 없고 재료가 공정 초에 투입되면 재료 환산량은 당기 착수량과 같다"],["계산 예","기초 2,000단위(30%), 착수 9,000단위, 완성 7,000단위, 기말 4,000단위(70%)이면 재료 환산량 9,000단위, 전환원가 환산량 1,400+5,000+2,800=9,200단위이다 · 당기원가 216,000원과 276,000원을 나누면 단가는 24원과 30원이고 완성품원가는 기초재공품 65,400원+42,000원+270,000원=377,400원이다"],["두 방법의 비교","평균법 환산량에서 선입선출법 환산량을 빼면 기초재공품의 환산량이 남으므로 기초재공품이 없으면 두 방법의 결과가 같다"],["역산","당기제품제조원가는 매출원가에서 기초제품을 빼고 기말제품을 더해 구하고, 이를 기초재공품+당기원가-기말재공품 식에 넣어 기초재공품이나 단위원가를 역산한다"]]},{"t":"table","title":"공손","head":["구분","내용"],"rows":[["정상공손","효율적인 생산에서도 피할 수 없는 공손으로 합격품 수량에 허용률을 곱해 정하고, 이를 넘는 공손은 비정상공손이다"],["합격품","당기에 검사시점을 통과한 물량이며 기말재공품 완성도가 검사시점 이상이면 합격품에 넣는다"],["기초재공품 완성도","선입선출법에서 기초재공품 완성도가 이미 검사시점을 넘었으면 전기에 검사를 통과한 것이어서 당기 합격품에서 뺀다"],["공손품 원가","재료원가에 전환원가 단가×검사시점 완성도를 더한 단위원가로 계산한다"],["정상공손원가","합격품원가에 가산하며 기말재공품도 검사를 통과했으면 합격품 수량 비율로 나누어 배분한다"],["비정상공손원가","기간비용으로 처리한다 · 검사 60% 시점, 재료 4원·전환원가 10원이면 공손품 단위원가는 4+10×60%=10원이다"]]},{"t":"table","title":"검사시점과 의사결정","head":["구분","내용"],"rows":[["검사시점을 앞당길 때","검사시점을 앞당겨 비정상공손품을 정상 완성품으로 바꿀 수 있으면 그 단위의 원가는 공손손실 대신 매출원가로 비용이 되어 총비용은 그대로이다"],["이익 증가","추가 원가가 없다면 이익은 늘어나는 판매량×판매가격만큼 증가하며 100단위를 단위당 250원에 더 팔면 25,000원이 늘어난다"]]}],"26":[{"t":"table","title":"결합원가와 배분 방법","head":["구분","내용"],"rows":[["결합원가","하나의 공정에서 여러 제품이 함께 생산될 때 분리점까지 발생한 공통원가이다"],["추가가공원가","분리점 이후 제품별로 추적되는 추가가공원가(개별원가)는 해당 제품에 직접 더한다"],["연산품·부산물","상대적 판매가치가 큰 제품은 연산품(주산품), 작은 제품은 부산물로 구분한다"],["물량기준법","생산량 비율로 나눈다"],["분리점 판매가치법","분리점 판매가치 비율로 나눈다"],["순실현가치법","최종 판매가치에서 추가가공원가(와 판매비)를 뺀 순실현가치 비율로 나눈다"],["균등매출총이익률법","모든 제품의 매출총이익률이 회사 전체 매출총이익률과 같아지도록 나눈다"]]},{"t":"table","title":"다단계 순실현가치법과 균등매출총이익률법","head":["구분","내용"],"rows":[["다단계 순실현가치법","중간 제품이 다시 결합공정을 거치면 뒤 단계 제품들의 순실현가치 합계에서 그 단계의 결합원가를 빼 중간 제품의 분리점 순실현가치를 구한다"],["계산 예","C(150,000원)와 D(100,000원)로 갈라지는 B의 순실현가치는 250,000-70,000=180,000원이고, 제1공정 결합원가 100,000원은 A(45,000원)와 B에 45:180으로 나누어 B가 80,000원을 받는다 · D는 (80,000+70,000)×100/250=60,000원에 추가원가 20,000원을 더해 총원가 80,000원이다"],["균등매출총이익률법 계산","전체 매출총이익률은 (총매출-결합원가-추가가공원가 합계)÷총매출이다 · 제품별 총원가는 그 제품 매출×(1-매출총이익률)이고 여기서 그 제품의 추가가공원가를 빼면 결합원가 배부액이다"],["계산 예","매출 X 300,000원·Y 200,000원, 결합원가 350,000원, 추가가공원가 X 30,000원·Y 20,000원이면 이익률 20%이고 배부액은 X 210,000원, Y 140,000원이다"]]},{"t":"table","title":"부산물","head":["구분","내용"],"rows":[["생산기준법","부산물을 생산 시점에 순실현가치로 재고자산으로 인식하고 그만큼 결합원가나 관련 추가가공원가에서 뺀다"],["판매기준법","부산물에 원가를 배분하지 않고 판매할 때 잡이익 등으로 인식한다"],["계산 예","추가가공 중 부산물 400원이 생기면 생산기준법에서는 추가가공원가 12,400원에서 400원을 뺀 12,000원으로 주산품 순실현가치를 계산한다"]]},{"t":"table","title":"추가가공 의사결정과 역산","head":["구분","내용"],"rows":[["추가가공 의사결정","결합원가는 분리점 전에 이미 발생한 매몰원가이므로 추가가공 여부 판단에 쓰지 않는다 · 추가가공 후 판매가치에서 분리점 판매가치를 뺀 증분수익이 추가가공원가보다 크면 추가가공한다"],["계산 예","B를 추가가공하면 375,000-330,000-60,000=-15,000원이므로 분리점에서 팔면 이익이 15,000원 늘어나고, 이 결론은 결합원가 배분 방법과 상관없다"],["순실현가치법 역산","어느 제품의 결합원가 배부액은 총결합원가×(그 제품 순실현가치÷전체 순실현가치)이므로 배부액이 주어지면 다른 제품의 순실현가치를 역산할 수 있다"],["역산 예","총결합원가 600,000원 중 X(순실현가치 120,000원)가 150,000원을 받으면 Y의 순실현가치는 360,000원이고 추가원가 36,000원을 더한 최종 판매가치를 3,600개로 나누면 단가 110원이다"]]}],"27":[{"t":"table","title":"직접재료원가·직접노무원가 차이","head":["구분","내용"],"rows":[["재료 가격차이","(실제가격-표준가격)×실제수량이고, 구매시점에서 분리하면 실제 구매량을, 사용시점에서 분리하면 실제 사용량을 곱한다"],["재료 수량(능률)차이","(실제사용량-실제산출량에 허용된 표준수량)×표준가격이다"],["재료 계산 예","구매 3,100kg을 표준 50원보다 10원 비싸게 사면 가격차이는 31,000원 불리하고, 표준 3,000kg에 실제 2,900kg을 쓰면 수량차이는 5,000원 유리하다"],["임률차이","(실제임률-표준임률)×실제시간이다"],["노무 능률차이","(실제시간-허용 표준시간)×표준임률이다 · 대체 가능한 노무등급이 여럿이면 능률차이를 배합차이와 수율차이로 나눈다"],["배합차이","(등급별 실제시간-실제 총시간×표준배합비율)×등급별 표준임률의 합이다"],["수율차이","(실제 총시간-허용 총표준시간)×표준배합 평균임률이다"]]},{"t":"table","title":"변동제조간접원가 차이와 뱃치 단위 원가동인","head":["구분","내용"],"rows":[["소비차이","실제 발생액-실제 배부기준량×표준배부율이다"],["능률차이","(실제 배부기준량-허용 표준 배부기준량)×표준배부율이다 · 배부기준이 직접노무시간이면 변동제조간접원가 능률차이와 직접노무원가 능률차이는 같은 시간 차이에서 나오므로 방향이 같다"],["계산 예","변동제조간접원가 능률차이 12,000원 불리(배부율 1,200원)면 10시간 초과이고 표준임률 2,000원이면 직접노무원가 능률차이는 20,000원 불리이다"],["뱃치 단위 원가동인","작업준비처럼 뱃치마다 생기는 원가는 허용 표준시간을 실제 생산량÷표준 뱃치크기×뱃치당 표준시간으로 구한다"],["뱃치 계산 예","예산 50시간·1,500원이면 표준배부율 30원이고, 실제 11,000단위(뱃치 200단위, 뱃치당 0.8시간)에 1,100원이 들면 실제 44시간, 허용 55시간이다 · 그러면 소비차이 220원 유리, 능률차이 330원 유리이다"]]},{"t":"table","title":"고정제조간접원가 차이와 변동예산","head":["구분","내용"],"rows":[["예산(소비)차이","실제 발생액-고정제조간접원가 예산이다"],["조업도차이","예산-허용 표준조업도×표준배부율이다 · 표준배부율은 예산을 기준조업도(정상조업도나 실제최대조업도)로 나눈 값이어서 실제 생산이 기준조업도보다 많으면 조업도차이는 유리하다"],["계산 예","예산 60,000원, 기준 12,000시간이면 배부율 5원이고 허용 표준시간 15,000시간이면 조업도차이는 15,000원 유리하다"],["변동예산","실제 활동량(실제 판매량·원가동인 수)에 맞추어 다시 계산한 예산이다"],["고정예산차이","매출조업도차이(변동예산-고정예산)와 변동예산차이(실제-변동예산)로 나뉜다 · 강좌 수와 학생 수처럼 원가동인이 여럿이면 각 동인의 실제 수량으로 변동예산을 다시 짠다"]]},{"t":"table","title":"매출차이와 생산성 변동","head":["구분","내용"],"rows":[["매출가격차이","(실제 판매가격-예산 판매가격)×실제 판매량이다"],["매출수량(조업도)차이","(실제 판매량-예산 판매량)×예산 단위당 공헌이익이며 영업이익 기준 분석에서는 매출액이 아니라 공헌이익을 쓴다"],["계산 예","예산단가 10원, 실제 27,500단위 매출 253,000원이면 가격차이 22,000원 불리, 예산 25,000단위·단위당 공헌이익 2.5원이면 수량차이 6,250원 유리이다"],["시장점유율차이","(실제 점유율-예산 점유율)×실제 시장규모×예산 단위당 공헌이익이다"],["시장규모차이","(실제 시장규모-예산 시장규모)×예산 점유율×예산 단위당 공헌이익이다"],["매출배합차이","여러 제품이면 (제품별 실제 판매량-실제 총판매량×예산 배합비율)×그 제품 예산 단위당 공헌이익이다 · 실제 X 54개, 예산 배합대로면 63개, 단위당 공헌이익 30,000원이면 X의 배합차이는 270,000원 불리하다"],["생산성 변동 분석","생산성 변동효과는 전기의 생산 효율(투입량÷산출량)로 당기 산출량을 만들 때 필요했을 투입량과 실제 투입량의 차이에 당기 가격을 곱해 구한다 · 전기 단위당 10kg으로 150단위면 1,500kg이 필요한데 실제 1,200kg을 쓰면 300kg×20원=6,000원 유리하다"]]}],"28":[{"t":"table","title":"세 방법의 제품원가","head":["방법","제품원가"],"rows":[["전부원가계산","직접재료원가·직접노무원가·변동제조간접원가·고정제조간접원가를 모두 제품원가에 넣는다"],["변동원가계산","변동제조원가만 제품원가로 하고 고정제조간접원가를 기간비용으로 처리한다"],["초변동원가계산","직접재료원가만 제품원가로 보고 직접노무원가와 제조간접원가를 모두 운영비용(기간비용)으로 처리한다"],["판매관리비","판매관리비는 세 방법 모두 기간비용이다"]]},{"t":"table","title":"전부원가와 변동원가의 이익 차이","head":["구분","내용"],"rows":[["이익 차이","전부원가 이익-변동원가 이익=기말재고에 포함된 고정제조간접원가-기초재고에 포함된 고정제조간접원가이다"],["재고의 증감","생산량이 판매량보다 많아 재고가 늘면 전부원가 이익이 더 크고, 재고가 줄면 변동원가 이익이 더 크다"],["선입선출법","기초재고의 고정제조간접원가를 전기 단위당 금액으로, 기말재고는 당기 단위당 금액으로 계산한다"],["계산 예","4,000단위를 생산해 3,000단위를 팔고 고정제조간접원가가 600,000원이면 단위당 150원이 기말재고 1,000단위에 묶이므로 전부원가 이익이 150,000원 크다 · 변동원가 이익이 4,400,000원이면 전부원가 이익은 4,550,000원이다"],["재고 소진 예","1월 생산분 기초재고 3,000단위(단위당 200원)를 2월에 모두 팔면 2월 전부원가 이익이 600,000원 작다"]]},{"t":"table","title":"변동원가와 초변동원가의 이익 차이·누적 기간","head":["구분","내용"],"rows":[["변동원가와 초변동원가의 차이","변동원가 이익-초변동원가 이익은 재고 증감분에 포함된 직접노무원가와 변동제조간접원가(직접재료원가 외 변동제조원가)이다"],["계산 예","500개 생산, 300개 판매에서 두 이익 차이가 360,000원이면 직접노무원가(유일한 변동가공원가) 총액은 360,000÷(200/500)=900,000원이다"],["이익 크기 순서","재고가 늘어날 때 영업이익 크기는 전부원가≥변동원가≥초변동원가 순이다"],["누적 기간","여러 기간을 합쳐 누적 생산량과 누적 판매량이 같으면 재고에 묶였다 풀린 고정제조간접원가가 상쇄되어 방법별 누적 영업이익이 같다"],["기간별 단가","기간별로 단위당 고정제조간접원가가 다르면 선입선출 가정에 따라 판매된 재고의 원가를 기간별 단가로 나누어 매출원가를 구한다"]]},{"t":"table","title":"각 방법의 쓰임과 공헌이익 손익계산서","head":["구분","내용"],"rows":[["전부원가계산의 쓰임","외부보고용으로 인정되지만 생산량을 늘리면 고정제조간접원가가 재고로 넘어가 이익이 커지므로 과잉생산 유인이 있다"],["변동원가계산의 쓰임","이익이 판매량에 따라 움직이고 원가-조업도-이익 분석과 내부 의사결정에 쓰인다"],["초변동원가계산의 쓰임","재고에 넣는 원가가 가장 적어 과잉생산을 가장 강하게 억제한다"],["공헌이익","매출액에서 모든 변동원가(변동판매관리비 포함)를 뺀 금액이다"],["부문이익","부문 공헌이익에서 그 부문에 추적 가능한 고정원가만 뺀 금액이며 추적 불가능한 공통원가는 배분하지 않는다 · 지역 A에서 25,000단위를 단위당 공헌이익 36원에 팔고 추적가능 고정원가가 150,000원이면 부문이익은 750,000원이다"]]}],"29":[{"t":"table","title":"고저점법·회귀분석·학습곡선","head":["구분","내용"],"rows":[["고저점법","원가가 아니라 조업도가 가장 높은 점과 가장 낮은 점 두 개만 써서 단위당 변동원가=(원가 차이÷조업도 차이)와 고정원가를 구한다 · 조업도 2,130개·1,427,600원과 1,020개·850,400원이면 단위당 변동원가 520원, 고정원가 320,000원이다"],["회귀분석","결정계수(R²)는 0과 1 사이이며 1에 가까울수록 설명력이 높고, t값이 크고 유의도가 낮을수록 계수를 신뢰할 수 있다"],["누적평균시간 모형","누적 생산량이 두 배가 될 때마다 누적 평균시간이 학습률만큼 줄고, 증분단위시간 모형은 마지막 한 단위의 시간이 학습률만큼 준다"],["학습곡선 계산 예","첫 500단위 평균 2시간, 80% 누적평균 모형이면 2,000단위 평균은 2×0.8×0.8=1.28시간이다 · 첫 50단위 평균 10시간이 200단위에서 10r²시간이 되므로 단위원가로 r을 역산할 수 있다"]]},{"t":"table","title":"손익분기점·안전한계·영업레버리지도","head":["구분","내용"],"rows":[["손익분기점","손익분기 판매량은 고정원가÷단위당 공헌이익, 손익분기 매출액은 고정원가÷공헌이익률이다"],["목표이익","목표 세후이익이 있으면 세전 목표이익=세후이익÷(1-세율)로 바꿔 고정원가에 더한다 · 손익분기점은 세전이익이 0인 점이므로 법인세율이 바뀌어도 손익분기 매출액은 변하지 않는다"],["안전한계","실제(예산) 매출액에서 손익분기 매출액을 뺀 금액이고 안전한계율은 이를 매출액으로 나눈 비율이다"],["영업레버리지도(DOL)","공헌이익÷영업이익이며 안전한계율의 역수여서 안전한계율이 높으면 DOL은 낮다 · DOL 3은 매출액이 1% 변할 때 영업이익이 3% 변한다는 뜻이고, 공헌이익 362,500원·영업이익 62,500원이면 DOL은 5.8이다"]]},{"t":"table","title":"복수 제품의 CVP","head":["구분","내용"],"rows":[["매출배합","매출배합이 일정하다고 가정하고 가중평균 단위당 공헌이익(또는 가중평균 공헌이익률)으로 전체 손익분기점을 구한 뒤 배합비율로 제품별로 나눈다"],["계산 예","배합 50:30:20, 단위당 공헌이익 500·400·150원이면 평균 400원이고 고정원가 920,000원이면 전체 손익분기 판매량은 2,300단위이다"],["제품 중단","C를 중단해 배합이 60:40이 되면 평균 460원, 전체 2,000단위, A는 1,200단위이다"]]},{"t":"table","title":"원가행태 판단·구간 가격·전부원가 손익분기점","head":["구분","내용"],"rows":[["고정원가","실제 판매 여부와 관계없이 운영 기간 내내 발생하는 객실 보수유지비 같은 원가는 고정원가이다"],["변동원가","판매(임대)될 때만 생기는 청소비가 변동원가이다"],["구간 가격","판매가격이 구간별로 다르면 구간마다 단위당 공헌이익을 따로 계산해 고정원가가 회수되는 지점을 찾는다 · 첫 5,000개 공헌이익 200,000원으로 고정비 280,000원이 남으면 다음 구간 단위당 20원으로 4,000개를 더 팔아야 하므로 손익분기점은 9,000개이다"],["변동원가계산의 손익분기점","고정원가 전체를 단위당 공헌이익으로 나누므로 생산량과 판매량이 달라도 변하지 않는다"],["전부원가계산의 손익분기점","고정제조간접원가가 제품원가에 들어가 생산량에 따라 손익분기점이 달라지며 (판매가격-전부원가 단위원가-단위당 변동판매관리비)로 고정판매관리비를 나누어 구한다 · 판매가 10,000원, 전부원가 단위원가 8,000원, 고정판매관리비 3,000,000원이면 1,500단위이다"]]}],"30":[{"t":"table","title":"관련원가·특별주문·자가제조","head":["구분","내용"],"rows":[["관련원가","대안마다 달라지는 미래원가이며 이미 발생해 되돌릴 수 없는 매몰원가는 관련원가가 아니다"],["의사결정에서 빼는 원가","다른 용도로 쓰거나 팔 수 없는 전용설비의 감가상각비, 대안과 관계없이 계속 생기는 공통고정비 배분액은 의사결정에서 뺀다"],["기회원가","자원을 다른 곳에 썼을 때 얻을 수 있었던 공헌이익(기회원가)은 관련원가에 넣는다"],["특별주문","여유 생산능력 안에서는 특별주문 가격과 증분 변동원가(절감되는 변동비는 빼고 추가되는 비용은 더함)의 차이만 비교하고 기존 고정원가는 무시한다 · 생산능력을 넘는 부분은 포기하는 기존 판매의 공헌이익과 외부 구입 원가 중 작은 쪽을 기회원가로 반영한다"],["특별주문 계산 예","3,000개 주문(단위당 공헌이익 25원)에 추가 고정비 20,000원, 기존 판매 500개(단위당 70원) 포기가 따르면 이익은 20,000원 증가한다"],["자가제조와 외부구입","외부에서 사면 회피할 수 있는 원가(변동제조원가, 회피 가능한 감독자 급여 등)와 설비를 다른 용도로 쓸 때 얻는 기회원가를 합해 외부 구입가격과 비교한다 · 회피가능 원가가 단위당 133원이고 공장부지 활용 공헌이익 240,000원을 10,000개로 나눈 24원을 더하면 무차별 구입가격은 157원이다"]]},{"t":"table","title":"제품라인 폐지와 제약자원","head":["구분","내용"],"rows":[["제품라인 폐지","제품을 중단하면 그 제품의 공헌이익을 잃는 대신 추적가능하고 회피가능한 고정원가를 아끼고 다른 제품 판매가 늘어나는 공헌이익을 얻는다"],["회피가능 고정원가","단위당 고정원가는 최대조업도 기준 금액이므로 회피가능 고정원가 총액은 단위당 금액×최대조업도로 구한다"],["폐지 계산 예","B 공헌이익 960,000원을 잃고 A·C 증가분 500,000원과 회피가능 고정원가 800,000원을 얻으면 이익은 340,000원 늘어난다"],["제약자원 하의 제품배합","자원 하나가 제약되면 제품 단위당 공헌이익이 아니라 제약자원 한 단위당 공헌이익이 큰 제품부터 시장수요 한도까지 생산한다"],["제품배합 계산 예","재료 4,000kg 제약에서 A는 kg당 130원, B는 kg당 120원이면 A 800단위(3,200kg)를 먼저 만들고 남은 800kg으로 B 160단위를 만들어 최대공헌이익 512,000원을 얻는다"]]},{"t":"table","title":"제약 상태의 특별주문과 정보의 가치","head":["구분","내용"],"rows":[["제약 상태의 특별주문","특별주문에 필요한 자원이 여유분보다 많으면 제약자원당 공헌이익이 가장 낮은 기존 제품부터 줄이고 그 공헌이익을 기회원가로 넣는다"],["최저 수용가격","단위당 변동원가에 (기회원가+목표 증분이익)÷주문량을 더해 구한다 · 기회원가 120,000원과 목표 180,000원을 500단위로 나누면 600원이므로 변동원가 800원에 더한 1,400원이 필요한 가격이다"],["완전정보의 기대가치","상황마다 최적 대안을 고를 수 있을 때의 기대이익에서 현재 정보로 고른 최적 대안의 기대이익을 뺀 금액이고 정보에 지불할 수 있는 최대 금액이다 · 기존 최적 기대이익 160,000원, 완전정보 하 177,000원이면 완전정보 가치는 17,000원이다"],["예측오차의 원가","실제 상황에서 최적이었을 이익과 선택한 대안의 실제 이익의 차이이다"]]},{"t":"table","title":"기대가치 응용","head":["구분","내용"],"rows":[["균등분포","판매량이 일정 구간에서 균등분포이면 기대판매량은 구간의 중간값이므로 1,200~1,800단위는 1,500단위, 1,500~2,000단위는 1,750단위이다"],["광고 효과","단위당 공헌이익 25원이면 광고로 기대공헌이익이 6,250원 늘고 광고비 5,000원을 빼 1,250원 이익이 증가한다"],["유리한 대안","두 대안의 기대현금흐름이 같아지는 확률을 구하면 어느 확률부터 대안이 유리한지 판단할 수 있다"]]}],"31":[{"t":"table","title":"자본예산과 현금흐름","head":["구분","내용"],"rows":[["자본예산","효과가 여러 해에 걸치는 설비투자 같은 장기 투자안을 평가하는 의사결정이다"],["평가 기준","회계이익이 아니라 증분 현금흐름을 기준으로 하며 최초 투자액, 운영 기간의 순현금유입, 종료 시점의 처분가치와 운전자본 회수로 나누어 추정한다"],["이자비용","이자비용은 할인율에 반영되므로 현금흐름에서 다시 빼지 않는다"],["감가상각 감세효과","감가상각비는 현금유출이 아니지만 과세소득을 줄여 감가상각비×세율만큼 세금을 아끼므로 이 감세효과가 현금유입이 된다"],["세후 영업현금흐름","(현금수익-현금비용)×(1-세율)+감가상각비×세율이다"],["설비 처분","처분가액에서 처분손익에 대한 세금(처분이익이면 유출, 처분손실이면 절감)을 반영한다"]]},{"t":"table","title":"평가 방법","head":["구분","내용"],"rows":[["순현재가치법(NPV)","미래 현금흐름을 자본비용으로 할인한 현재가치에서 투자액을 뺀 금액이며 0보다 크면 채택한다 · 화폐의 시간가치와 모든 현금흐름을 반영하고 가치가산의 원칙이 성립해 상호배타적 투자안 비교에 가장 적합하다 · 재투자수익률을 자본비용으로 가정한다"],["내부수익률법(IRR)","순현재가치를 0으로 만드는 할인율이며 자본비용보다 크면 채택한다 · 재투자수익률을 내부수익률 자체로 가정하고 현금흐름 부호가 여러 번 바뀌면 내부수익률이 여러 개 나오거나 없을 수 있다 · 상호배타적 투자안은 규모나 현금흐름 시기 차이 때문에 순현재가치법과 순위가 다를 수 있으며 이때 순현재가치법을 따른다"],["회수기간법","투자액을 회수하는 데 걸리는 기간으로 평가해 간단하고 유동성을 보여 주지만 화폐의 시간가치와 회수기간 이후 현금흐름을 무시한다"],["할인회수기간법","시간가치는 반영하지만 회수 이후 현금흐름은 여전히 무시한다"],["회계적이익률법","연평균 회계이익을 투자액(또는 평균투자액)으로 나누어 평가하며 현금흐름이 아니라 회계이익을 쓰고 시간가치를 무시한다"]]},{"t":"table","title":"인플레이션과 할인율","head":["구분","내용"],"rows":[["명목과 실질","명목 현금흐름은 명목 할인율로, 실질 현금흐름은 실질 할인율로 할인해야 같은 결과가 나온다"],["할인율의 관계","명목 할인율과 실질 할인율의 관계는 (1+명목)=(1+실질)×(1+물가상승률)이다"],["감가상각 감세효과","취득원가에 고정되어 물가와 함께 오르지 않으므로 명목 금액으로 다룬다"]]}],"32":[{"t":"table","title":"책임중심점과 예산","head":["구분","내용"],"rows":[["책임중심점","원가중심점(생산·인사·재무부문), 수익중심점(판매부문), 이익중심점, 투자중심점으로 나눈다"],["통제가능성","책임회계는 통제가능성 원칙에 따라 관리자가 통제할 수 있는 항목으로만 평가하므로 공통고정원가는 책임중심점에 배부하지 않는다"],["상대평가","경기처럼 통제할 수 없는 요소를 걸러 내는 데에는 동종 집단과 비교하는 상대평가가 절대평가보다 유용하다"],["종합예산","각 부문 예산을 합친 조직 전체 예산이며 하나의 예정조업도를 기준으로 짜므로 고정예산이다 · 성과평가에는 실제 조업도에 맞춘 변동예산을 쓴다"],["원점기준예산·참여예산","원점기준예산은 과거 예산과 관계없이 새로 짜고, 참여예산은 종업원의 책임감을 높이지만 예산슬랙(예산여유)이 생길 가능성을 높인다"]]},{"t":"table","title":"예산 편성 계산","head":["구분","내용"],"rows":[["상품 매입액","당월 매출원가에 월말 목표재고를 더하고 월초재고를 뺀 금액이며 월말재고를 다음 달 매출원가의 일정 비율로 정하면 비율 변화가 매입액을 바꾼다"],["현금유입","매출 회수 패턴(당월·익월 회수 비율)으로 구한다"],["계산 예","2월 매출 150,000원(30% 당월 회수)과 1월 매출 100,000원(70% 익월 회수)이면 유입은 115,000원, 매입 85,200원과 판매관리비 9,000원을 빼면 순현금 20,800원이다"]]},{"t":"table","title":"투자수익률과 잔여이익","head":["구분","내용"],"rows":[["투자수익률(ROI)","영업이익÷평균영업자산이며 매출액이익률×자산회전율로 나눌 수 있다"],["준최적화","사업부의 현재 투자수익률보다 낮지만 최저필수수익률보다 높은 투자안을 사업부가 거부하면 회사 전체에는 손해가 되는 준최적화가 생길 수 있다 · 이 문제를 보완하려고 잔여이익을 쓴다"],["잔여이익(RI)","영업이익-평균영업자산×최저필수수익률이다 · 영업이익 200,000원, 자산 625,000원 사업부가 120,000원을 투자해 영업이익 30,000원을 더 벌면 최저필수수익률 15%에서 잔여이익은 230,000-745,000×15%=118,250원이다 · 잔여이익은 금액이어서 규모가 다른 사업부끼리 비교하기 어렵다"],["경제적 부가가치(EVA)","세후영업이익-투하자본×가중평균자본비용이다 · 영업이익 300,000원, 세율 40%, 투하자본 1,000,000원, 가중평균자본비용 10%이면 EVA는 180,000-100,000=80,000원이고, 같은 자산에 최저필수수익률 15%를 쓴 잔여이익은 150,000원이다"]]},{"t":"table","title":"대체가격","head":["구분","내용"],"rows":[["최소 대체가격","공급사업부의 최소 대체가격은 대체 시 단위당 증분 변동원가(내부대체로 절감되는 판매비는 뺌)에 단위당 기회원가를 더한 금액이다"],["기회원가","생산능력을 모두 외부판매에 쓰고 있으면 포기하는 외부판매 공헌이익이 기회원가이고 유휴 생산능력이 있으면 기회원가는 0이다"],["계산 예","외부가 90원, 변동원가 60원, 대체 시 20원 절감이면 최소 대체가격은 40+30=70원이며 구매사업부의 최대 가격은 외부 구입가격이다"],["시장가격","외부시장이 완전경쟁적이고 공급부문에 유휴 생산능력이 없으면 시장가격이 기업 전체 이익을 최대화하며 목표일치성·성과평가·자율성 기준을 모두 충족할 수 있다"],["전부원가 기준","전부원가 기준 대체가격은 회사 전체와 사업부의 최적 결정이 어긋나는 준최적화를 낳을 수 있다"],["표준원가·예산 기준","표준원가나 예산을 대체가격에 쓰면 원가절감 동기를 주지만 표준 달성 여부가 부문 성과평가에 영향을 미친다"]]}],"33":[{"t":"table","title":"가격결정과 품질원가","head":["구분","내용"],"rows":[["원가가산 가격결정","원가(전부원가나 변동원가)에 일정 이윤폭을 더해 가격을 정하고, 장기적으로는 고정원가까지 회수할 수 있는 가격이어야 한다"],["목표가격 결정","시장에서 받아들여질 가격을 먼저 정하고 목표이익을 빼 허용 원가를 정한다"],["단기 최저가격","일회성 특별주문의 단기 최저가격은 증분원가에 기회원가를 더한 금액이다"],["예방원가","불량을 미리 막는 원가로 품질교육, 품질관리 계획, 우수 협력업체 조달, 품질개선 설계가 있다"],["평가원가","원재료·공정·완성품 검사와 검사설비 유지비이다"],["내부실패원가","출하 전 발견한 불량의 폐기·재작업 원가이다"],["외부실패원가","보증수리·반품·리콜과 평판 악화로 잃는 판매기회(기회원가)이며 보통 가장 크다"]]},{"t":"table","title":"품질원가의 관계와 목표원가계산","head":["구분","내용"],"rows":[["통제원가와 실패원가","통제원가(예방원가+평가원가)를 늘리면 실패원가가 줄어 둘은 음(-)의 관계이고, 품질이 높아질수록 실패원가는 낮아진다"],["계산 예","예방 7,700원, 평가 13,400원, 내부실패 13,500원, 외부실패 34,000원에서 예방을 50% 늘려 내부실패 20%, 외부실패 10%를 줄이면 총 품질원가는 68,600원에서 66,350원이 된다"],["목표원가계산","목표가격에서 목표이익을 뺀 목표원가를 정하고 제품 개발·설계 단계(제조 이전)에서 원가를 낮춘다"],["카이젠원가계산","제조 단계에서 작은 개선을 계속 쌓아 원가를 낮춘다"],["바탕","원가의 대부분이 설계 단계에서 결정된다는 인식이 목표원가계산의 바탕이다"]]},{"t":"table","title":"수명주기원가·제약이론·JIT","head":["구분","내용"],"rows":[["제품수명주기원가계산","제품이 고안된 때부터 폐기될 때까지의 모든 원가를 식별해 측정하며 제조 이전 단계에서 원가 대부분이 정해진다고 보고 그 단계의 절감을 강조한다"],["가치사슬원가계산","연구개발·설계 같은 생산 전 활동과 마케팅·고객서비스 같은 생산 후 활동의 원가를 구분한다"],["활동기준경영(ABM)","활동과 프로세스 개선으로 가치를 높이는 것은 활동기준경영(ABM)이다"],["제약이론","병목공정의 처리능력 제약을 푸는 데 집중해 성과를 높인다 · 재료처리량공헌이익은 매출액에서 직접재료원가만 빼고 나머지 운영원가는 고정원가로 본다"],["병목 뒤의 불량","병목공정 뒤에서 불량이 발견되면 병목 시간을 날린 것이어서 그 수량만큼의 매출이 그대로 사라지며 단위당 50원짜리 100단위면 이익이 5,000원 줄어든다"],["적시생산시스템(JIT)","필요한 때 필요한 만큼 만들어 재고를 최소화하므로 안전재고를 낮게 유지한다 · 작업은 제조 셀을 중심으로 이루어지고, 재고가 거의 없어 원재료·재공품 계정을 따로 관리할 필요가 적어 역류원가계산을 쓴다"],["안전재고","재고 부족으로 판매기회를 놓치는 손실을 줄이는 대신 보유원가가 든다"]]},{"t":"table","title":"균형성과표","head":["구분","내용"],"rows":[["균형성과표(BSC)","조직의 비전과 전략을 재무, 고객, 내부 프로세스, 학습과 성장의 4가지 관점 성과지표로 구체화해 전략 수행을 돕는다"],["보완","재무 지표 중심인 전통적 성과측정의 한계를 보완하며 비재무 지표는 재무 성과의 선행지표가 된다"],["인과관계","지표들 사이에 인과관계를 두고 수익성(재무 관점)을 최종 목표로 삼는다"]]}],"34":[{"t":"table","title":"법체계·회계실체와 결산","head":["구분","내용"],"rows":[["국가회계법","일반회계·특별회계·기금의 회계와 결산에 관해 다른 법률에 우선하여 적용되고, 2025.10.1 개정으로 국가회계 사무의 총괄과 국가회계기준(부령) 제정은 재정경제부장관이 맡는다"],["국가회계실체","일반회계·특별회계·기금으로서 중앙관서별로 구분된 것이며 공기업은 들어가지 않는다"],["지방자치단체 회계실체","개별 회계실체, 유형별 회계실체(일반회계·기타특별회계·기금회계·지방공기업특별회계), 통합 회계실체로 나뉜다"],["국가 결산 절차","중앙관서의 장은 일반회계·특별회계·기금을 통합한 중앙관서결산보고서를 다음 연도 2월 말일까지 재정경제부장관에게 내고, 국회·법원·헌법재판소·중앙선관위의 예비금사용명세서도 같은 기한에 재정경제부장관에게 낸다"],["국가결산보고서","재정경제부장관은 국가결산보고서를 국무회의 심의를 거쳐 대통령 승인을 받은 뒤 4월 10일까지 감사원과 기획예산처장관에게 내고, 감사원은 5월 20일까지 검사보고서를 보내며 정부는 5월 31일까지 국회에 제출한다"],["결산보고서의 구성","결산 개요, 세입세출결산, 재무제표, 성과보고서로 이루어지고 직전 연도 기금운용규모 5천억원 이상 기금의 결산보고서에는 회계법인 감사보고서를 붙인다"],["지방 결산","지방자치단체의 장은 결산 개요, 세입·세출결산, 재무제표(주석 포함), 성과보고서로 이루어진 결산서를 지방의회가 선임한 검사위원에게 검사받고, 결산 승인을 요청한 날부터 5일 이내에 행정안전부장관에게 낸다 · 재무제표에는 공인회계사의 감사의견이 아니라 검토의견을 붙이고 성인지 결산서를 첨부한다"],["출납기한","출납은 회계연도 말일에 폐쇄하되 예외적으로 다음 연도 1월 20일까지 수입·지출 처리할 수 있고 출납사무는 2월 10일까지 마친다"]]},{"t":"table","title":"재무제표 구성과 자산 인식","head":["구분","내용"],"rows":[["국가 재무제표","재정상태표, 재정운영표, 순자산변동표, 현금흐름표와 주석이며(2024.7.31 개정), 자산은 금융자산·유무형자산·기타자산, 부채는 차입부채·충당부채·기타부채, 순자산은 기본순자산·적립금 및 잉여금·순자산조정으로 나눈다"],["지방 재무제표","재정상태표·재정운영표·현금흐름표·순자산변동표·주석에 부속서류(필수보충정보·부속명세서)를 두고, 자산은 유동자산·투자자산·일반유형자산·주민편의시설·사회기반시설·기타비유동자산(무형자산 포함), 순자산은 고정순자산·특정순자산·일반순자산으로 나눈다"],["총액 표시","자산·부채는 총액으로 표시해 상계하지 않으며 출납정리(폐쇄)기한 중 거래는 해당 회계연도 거래로 본다"],["유산자산","국가의 유산자산은 자산으로 인식하지 않고 종류와 현황을 주석으로 공시하며 지방의 문화재·예술작품·역사적 문건·자연자원은 필수보충정보의 관리책임자산으로 보고한다"],["국가안보 관련 자산·부채","재정경제부장관과 협의해 인식하지 않을 수 있다"],["사용수익권","일반유형자산·사회기반시설(지방은 주민편의시설 포함)의 사용수익권은 해당 자산의 차감항목으로 표시하므로 BTO 방식 도로는 자산 순증가가 0이고, BTL 방식 건물은 임대료 지급의무를 부채로 인식해 자산이 그대로 늘어난다"]]},{"t":"table","title":"취득원가·감가상각과 평가","head":["구분","내용"],"rows":[["취득원가","교환·기부채납·무주부동산 취득은 공정가액이 취득원가이고, 국가회계실체 사이 관리전환은 무상이면 장부가액, 유상이면 공정가액이며 지방의 회계 간 재산 이관·물품 소관 전환은 직전 회계실체의 장부가액이다"],["감가상각","사회기반시설 중 관리·유지로 취득 당시 용역잠재력이 유지되는 것은 감가상각 대신 유지비로 대체할 수 있다 · 무형자산은 정액법으로 사용 가능 시점부터 상각하며 법령·계약에서 정한 경우 외에는 20년을 넘지 못한다"],["순자산조정","투자증권 공정가액 차이, 재평가이익(전에 재정운영결과로 인식한 재평가손실분은 제외), 보험수리적손익, 미래예상거래 현금흐름위험회피 파생상품 평가손익은 순자산조정이다"],["재정운영결과","정부출자금을 포함한 자산 감액손실, 화폐성 외화 환율변동효과, 그 밖의 파생상품 평가손익은 재정운영결과에 반영한다"],["부채 평가","원칙적으로 만기상환가액으로 평가하되 장기연불·장기금전대차 채권·채무는 차이가 중요하면 유효이자율(모르면 유사 조건 국채 수익률)로 할인한 현재가치로 평가한다"],["융자·연금","융자사업 대여금은 원금과 추정 회수가능액 현재가치의 차액을 융자보조원가충당금으로 설정하고 연금충당부채는 연금추정지급액 중 재직기간까지 귀속되는 금액의 현재가치로 평가한다"]]},{"t":"table","title":"재정운영표·순자산변동표·현금흐름표","head":["구분","내용"],"rows":[["재정운영순원가(중앙관서)","프로그램순원가(프로그램총원가-프로그램수익)에 관리운영비와 비배분비용을 더하고 비배분수익을 빼 재정운영순원가를 구하며 국고금으로 통합 관리되는 일반회계의 비교환수익은 재정운영표가 아니라 순자산변동표의 재원의 조달 및 이전에 둔다"],["수익 인식","신고·납부 국세는 자진신고 때, 부과 국세는 고지 때, 원천징수 국세는 원천징수의무자가 신고·납부할 때, 부담금·기부금·제재금은 청구권이 확정될 때 수익으로 인식한다"],["지방 재정운영결과","사업순원가+관리운영비+비배분비용-비배분수익으로 재정운영순원가를 구하고 일반수익(자체조달·정부간이전·기타수익)을 빼 재정운영결과를 내며 재산 이관·기부채납으로 늘어난 순자산은 수익이 아니라 순자산변동표 항목이다"],["순자산변동표","중앙관서·기금의 순자산변동표는 기초순자산, 재정운영결과, 재원의 조달 및 이전, 조정항목, 기말순자산으로 나누고 국가 순자산변동표에는 재원의 조달 및 이전이 없다"],["계산 예","기초 40,000원에서 재정운영결과 10,000원을 빼고 비교환수익 11,000원과 국고수입 20,000원을 더하고 국고이전지출 5,000원을 뺀 뒤 투자증권 평가이익 3,000원을 더하면 기말순자산은 59,000원이다"],["국가 현금흐름표","운영활동을 직접법으로 작성하고 국고수입·국고이전지출은 운영활동, 융자금 회수·건물 취득은 투자활동에 넣는다"],["오류수정","중대한 전기오류는 오류가 생긴 연도의 순자산에 반영해 비교재무제표를 다시 작성하고 그 밖의 오류는 당해 재정운영표에 반영한다"]]}]};
